-- 补充汉化：NPC 对白（npc_text.text0_N）。幂等：仅当当前仍是英文原文时更新。

-- One indexed pass replaces 319 single-row UPDATEs on `npc_text`.`text0_0`.
UPDATE `npc_text` AS `a`
JOIN (
    SELECT 'How may I help you?' AS `src`, '有什么可以帮你的吗？' AS `dst`
    UNION ALL SELECT 'Well, if it isn\'t a young, bristling $c, no doubt drawn here by talk of my exploits in fields of battle!$B$BNo time for stories now, for there are great, important deeds that need doing!  So if you\'re looking for glory, then luck shines on you today...' AS `src`, '哦，可不是个年轻气盛的 $c 嘛，多半是听说了我在战场上那些事迹才来到这儿的！$B$B不过现在没工夫讲故事，还有了不起的大事等着办呢！所以你要是来找荣耀的，今天可算走运了……' AS `dst`
    UNION ALL SELECT 'Another soldier on $ghis:her; way to Honor Hold... by Kurdran\'s beard, they can use the help!' AS `src`, '又一位士兵要踏上前往荣耀堡的路了……以库德兰的胡子起誓，他们确实需要帮手！' AS `dst`
    UNION ALL SELECT 'How may I assist you in the afterlife?' AS `src`, '在来世里，我能帮你什么忙吗？' AS `dst`
    UNION ALL SELECT 'Dey be on top of de tall building in de southeast end of de valley.' AS `src`, '他们就在山谷东南头那栋高楼的顶上。' AS `dst`
    UNION ALL SELECT 'The Darkmoon Faire is now open!$b$bFor a small fee, I can teleport you to the fairground staging area.$b$bWould you like to go?' AS `src`, '暗月马戏团现在已经开张！$b$b只需付一点小钱，我就能把你传送到集市的集结区。$b$b你想去吗？' AS `dst`
    UNION ALL SELECT 'Select your destination.' AS `src`, '请选择你的目的地。' AS `dst`
    UNION ALL SELECT 'Welcome, champions! All of our attempts at grounding her have failed. We could use a hand in bringing her down with these harpoon guns.' AS `src`, '欢迎，勇士们！我们所有想把她拽下来的尝试都失败了。要是你们能用这些鱼叉炮帮忙把她打下来，那可就帮大忙了。' AS `dst`
    UNION ALL SELECT 'Which profession?' AS `src`, '哪个专业？' AS `dst`
    UNION ALL SELECT 'Master Pyreanor can be found among Thrall\'s advisors in his fortress, Grommash Hold, in the Valley of Wisdom.' AS `src`, '派瑞诺大师在智者谷的格罗玛什要塞，就在萨尔的顾问中间。' AS `dst`
    UNION ALL SELECT 'I am a mage of great power, I have spent my days studying the mind and the memory as it pertains to learning and the retention of learned abilities. I would even now be perfecting my studies if not for the great voices that came to me in the night, informing me that my services were required. I will be here for only a short time offering my ability to wipe your talents for free. Soon I will leave again, and you will once more be stuck with whatever choices you make.' AS `src`, '我是一位法力强大的法师，这些年来我一直研究心智与记忆——尤其涉及学习以及所学能力的保持。若不是夜里那些伟大的声音降临，告知我的服务被需要，我此刻仍在完善我的研究。我只在这里停留很短一段时间，免费为你清除天赋。很快我又会离去，到那时你就只能将就自己做出的选择了。' AS `dst`
    UNION ALL SELECT 'The younger races make a big fuss over Winter Veil. Ironforge\'s bank is the center of the festivities.' AS `src`, '年轻的种族为冬幕节大做文章。铁炉堡的银行正是庆典的中心。' AS `dst`
    UNION ALL SELECT 'The largest celebration of the Lunar Festival takes place in Moonglade. Druids will transport you there from the Elder Rise of Thunder Bluff.' AS `src`, '最盛大的春节庆典在月光林地举行。德鲁伊们会从雷霆崖的长者高地把你送过去。' AS `dst`
    UNION ALL SELECT 'Go to Ironforge\'s Mystic Ward and speak with the night elf druids there. They can transport you to Moonglade to join in the Lunar Festival celebration.' AS `src`, '去铁炉堡的秘法区，找那里的暗夜精灵德鲁伊谈谈。他们能把你送到月光林地，参加春节庆典。' AS `dst`
    UNION ALL SELECT 'What? Where am I? This isn\'t right at all! Look at you! Look at this place! It isn\'t on my list! There\'s going to be so much paperwork...$b$b<The goblin writes frantically in a small notebook.>$b$bLook, if you\'ve got nothing better to do than stand there and stare, why don\'t you go visit my cousin, Kwee Q. Peddlefeet, in one of the major cities? Says here he\'s taking care of Orgrimmar, Stormwind, Thunder Bluff, Ironforge, the Undercity, and Darnassus. Go on, get outta here!' AS `src`, '什么？我这是在哪儿？这完全不对！看看你！看看这地方！这不在我的清单上！这下要填多少表格啊……$b$b<地精疯狂地在一本小本子上写着。>$b$b喂，你要是除了站在那儿发呆就没别的事，干吗不去找我的表亲奎·Q·叫卖脚，他在几座主城里呢？这儿写着，他负责奥格瑞玛、暴风城、雷霆崖、铁炉堡、幽暗城和达纳苏斯。去吧，出去吧！' AS `dst`
    UNION ALL SELECT 'When you\'re done visiting this exotic city, perhaps you would be interested in celebrating with us. The Lunar Festival is underway in Moonglade; the other cities have transport to the festivities. Come and join the other revelers!' AS `src`, '等你逛完这座异域城市，也许会有兴趣和我们一起庆祝。春节正在月光林地举行；其他城市都有通往庆典的交通。来和其他狂欢者一起吧！' AS `dst`
    UNION ALL SELECT 'Forgetting your skill in Spellfire Tailoring is not something to do lightly.  If you choose to abandon it you will forget all recipes that require Spellfire Tailoring to create!$b$bAre you absolutely sure?' AS `src`, '忘记你在魔火裁缝上的技能可不是件小事。如果你选择放弃，你将忘记所有需要魔火裁缝才能制作的配方！$b$b你绝对确定吗？' AS `dst`
    UNION ALL SELECT 'If you\'re looking to practice fire fighting, this is the place. There may be a heap of snow hereabouts, but you never know when Steelgrill or those gnomes\'ll cause an explosion, eh?' AS `src`, '要是你想练习救火，这地方正合适。周围也许堆满了雪，可谁知道钢炉或者那些侏儒什么时候会弄出爆炸来，嗯？' AS `dst`
    UNION ALL SELECT 'Good seein\' you again, $n.  I hope our club be treatin\' ya right.' AS `src`, '又见到你真好，$n。希望我们的俱乐部待你还算不错。' AS `dst`
    UNION ALL SELECT 'Hey, $n!  I hope you\'ve been enjoying our club!' AS `src`, '嘿，$n！希望我们俱乐部让你玩得开心！' AS `dst`
    UNION ALL SELECT 'The trickster Mage-Lord Urom protects the third ring.  He will appear alone and defenseless, but do not be fooled by appearances!  Urom is a powerful conjurer who commands a menagerie of Phantasmal creatures.  Seek him out above.' AS `src`, '诡诈的法师领主乌洛姆守卫着第三道环。他会独自出现，看似毫无防备，但别被表象骗了！乌洛姆是强大的召唤师，统领着一群幻影生物。到上面去找到他。' AS `dst`
    UNION ALL SELECT 'You are not yet strong enough to do battle in the Eye of the Storm. Return when you have gained more experience.' AS `src`, '你还不够强，无法在风暴之眼作战。等你获得更多经验后再回来。' AS `dst`
    UNION ALL SELECT 'Wait, $c....$b$bOne... final request...' AS `src`, '等等，$c……$b$b最后一个……请求……' AS `dst`
    UNION ALL SELECT '<Allyndia\'s body bobs gently in the surf. It appears that she\'s been dead for some time.>' AS `src`, '<艾琳迪娅的遗体在海浪中轻轻起伏。看样子她已经死去多时了。>' AS `dst`
    UNION ALL SELECT '<As you turn Barithras\' limp body over in the water, a brutal injury on his head makes it very apparent why he did not make it.>' AS `src`, '<当你把巴里瑟拉无力的身体在水中翻过来时，他头上那处可怕的伤清楚说明了为什么他没能活下来。>' AS `dst`
    UNION ALL SELECT '<Dalmond\'s body looks almost peaceful, buried only slightly in the sand..>' AS `src`, '<达尔蒙德的遗体看上去几乎很安详，只浅浅埋在沙里……>' AS `dst`
    UNION ALL SELECT '<Grondal reaches futilely towards you as you approach, but his arm collapses as life slips from him.>' AS `src`, '<格隆达尔在你靠近时徒劳地向你伸出手，可随着生命从他身上流逝，手臂垂了下去。>' AS `dst`
    UNION ALL SELECT '<Terenthis\' eyes stare unblinking into the distance, betraying the sorrow of his last moments.>' AS `src`, '<特伦西斯的双眼一眨不眨地凝视着远方，流露出他最后时刻的悲伤。>' AS `dst`
    UNION ALL SELECT '<The night elf turns to you as you approach and reaches for your hand.>\r\n\r\nIt is too late for me. We earned our fate with our pride. Go... others may have made it. Save any that you can.\r\n\r\n<Her grip loosens as life slips from her.>' AS `src`, '<当你靠近时，那名暗夜精灵转向你并伸出手。>\n\n已经太迟了。我们因自己的骄傲而招来这样的命运。走吧……也许还有人活着。能救的，都救下。\n\n<随着生命从她身上流逝，她的握力松开了。>' AS `dst`
    UNION ALL SELECT 'So this... is what it feels like... to be mortal?\r\n\r\n<The question trails off as Mavralyn\'s breathing stops.>' AS `src`, '原来……这就是凡人的感觉吗？\n\n<随着玛芙拉琳的呼吸停止，这个问题也消散了。>' AS `dst`
    UNION ALL SELECT '<As you approach, you hear Cerellean gasp for breath. He looks to stand a chance if rescued soon.>' AS `src`, '<你靠近时，听见塞雷利安在喘息。看样子如果很快获救，他还有机会活下来。>' AS `dst`
    UNION ALL SELECT '<Volcor\'s body lies motionless.  As you begin to move away, a hand reaches out and grabs your ankle. He\'s alive!>' AS `src`, '<沃尔科的遗体一动不动地躺着。就在你准备离开时，一只手伸出来抓住了你的脚踝。他还活着！>' AS `dst`
    UNION ALL SELECT '<A whisper escapes Shaldyn\'s throat as you approach.>\r\n\r\n\r\n\r\nHelp... please.' AS `src`, '<你靠近时，一阵低语从沙尔丁的喉咙里逸出。>\n\n\n\n救……救救我。' AS `dst`
    UNION ALL SELECT '<Gershala rolls onto his side to look at you as you approach and you see a hopeful smile creep onto his face.>' AS `src`, '<你靠近时，格沙拉翻身看向你，你能看到他脸上慢慢浮现出一丝希望的笑意。>' AS `dst`
    UNION ALL SELECT 'Me not workin\' til elfs is gone!' AS `src`, '精灵不走，我就不干活！' AS `dst`
    UNION ALL SELECT 'I am told Pilgrim\'s Bounty is a time to reflect upon one\'s good fortune and share with all around you.$B$BWe are lucky to have found this world and its bold inhabitants; it is only fitting that we lend our knowledge and strength to these new-found allies.' AS `src`, '听说朝圣者的恩典是反思自己好运、与身边所有人分享的时刻。$B$B我们很幸运能发现这个世界和这里勇敢的居民；把知识和力量借给这些新结识的盟友，再合适不过。' AS `dst`
    UNION ALL SELECT 'Humans can\'t brew their way out of a tattered linen pouch, but there sure know how to cook. Pilgrim\'s Bounty? I\'m all for it!' AS `src`, '人类的酿酒水平糟糕透顶，但烹调可真有一手。朝圣者的恩典？我全力支持！' AS `dst`
    UNION ALL SELECT 'The logistics involved in the optimal celebration of Pilgrim\'s Bounty are quite staggering... so many raw materials, so much labor, thousands upon thousands of crates of finished product shipped here and there and everywhere for countless Bountiful Tables.$B$BHonestly, I\'m quite impressed! And hungry... I can smell pumpkin pie. Can you smell that pie?' AS `src`, '要让朝圣者的恩典办得尽善尽美，后勤工作相当惊人……那么多原料，那么多人工，成千上万的成品箱子被运到这里、那里、到处，供无数恩典餐桌使用。$B$B说实话，我很佩服！而且很饿……我能闻到南瓜派的味道。你也闻到了吗？' AS `dst`
    UNION ALL SELECT 'The orcs and tauren are fortunate to have found one another, for each people\'s strengths compliment the other\'s.  We are glad to join them in this celebration.$B$BEven the Forsaken partake, though to what end I am not certain...' AS `src`, '兽人与牛头人能彼此相遇是件幸事，因为两个种族的强项正好互补。我们很高兴能和他们一起庆祝。$B$B就连被遗忘者也来参加，虽然我还不确定是为了什么……' AS `dst`
    UNION ALL SELECT 'Pilgrim\'s Bounty is a time to reflect upon one\'s good fortune and share with all around you.$B$BIn Mulgore and the Horde, we have found both a home and friends to enjoy its many fruits with.$B$BIt is our hope that every one of our allies will be able to join us in feasting and celebration.' AS `src`, '朝圣者的恩典是反思自己好运、与身边所有人分享的时刻。$B$B在莫高雷和部落，我们既找到了家，也找到了能共享其丰硕果实的友人。$B$B我们希望每一位盟友都能加入我们的盛宴与庆祝。' AS `dst`
    UNION ALL SELECT 'Dem tauren, dey be KNOWIN\' how ta cook. Have ya SEEN all de food dey be servin\'?$B$BI\'m gonna eat \'til I die... an\' den come back from de grave ta be eatin\' some more!' AS `src`, '那些牛头人，他们可真懂做饭。你见过他们端出来的那些菜吗？$B$B我要吃到死……然后从坟墓里爬回来再吃一点！' AS `dst`
    UNION ALL SELECT '$N? $G Sir : Ma\'am;, you\'re not a hunter, you\'re a $c.' AS `src`, '$N？$G先生：女士;，你不是猎人，你是个 $c。' AS `dst`
    UNION ALL SELECT 'Oh, you and I are going to have a great time. I have so much to teach you about the ways of the hunter.' AS `src`, '哦，你我将会相处得很愉快。关于猎人之道，我有很多东西要教你。' AS `dst`
    UNION ALL SELECT 'Hey there, $g Mr. : Ms.; $N. I can\'t train you in the ways of magic, but all of this finger-waggling means that I can give a mean neck massage.' AS `src`, '嘿，$g先生：女士; $N。我没法教你魔法之道，不过这些摇手指的把戏意味着我能给你做一次相当不错的颈部按摩。' AS `dst`
    UNION ALL SELECT 'What a wonderful day for some training in the mystical arts. Wouldn\'t you agree, $g Mr. : Ms.; $N?' AS `src`, '多美妙的天气，正适合研习神秘技艺。你不同意吗，$g先生：女士; $N？' AS `dst`
    UNION ALL SELECT 'The elements favor you.  What will you ask of them?' AS `src`, '元素眷顾着你。你会向它们祈求什么？' AS `dst`
    UNION ALL SELECT 'The elements are fickle and best left out of untrained hands.  My apologies, but I have no need for yours.' AS `src`, '元素反复无常，最好别落在未经训练的人手里。很抱歉，我不需要你的。' AS `dst`
    UNION ALL SELECT 'When d\'ye think we can leave?  I need ta get back to work.' AS `src`, '你觉得我们什么时候能走？我得回去干活了。' AS `dst`
    UNION ALL SELECT 'Only those who have the ranger general\'s approval may enter the Sunwell Plateau.' AS `src`, '只有获得游侠将军许可的人才能进入太阳井高地。' AS `dst`
    UNION ALL SELECT 'This ain\'t much of a big challenge, mon, but we gotta know ya can handle the pit before we can take ya in.' AS `src`, '这不算什么大挑战，老兄，但咱们得先看看你能不能应付这个场子，才谈得上收你。' AS `dst`
    UNION ALL SELECT 'They\'re in mid challenge, mon. Be patient.' AS `src`, '他们正在比试当中，老兄。耐心点。' AS `dst`
    UNION ALL SELECT 'I can\'t help ya. Go talk ta Zen\'Tabra if ya want druid trainin\'.' AS `src`, '我帮不了你。想学德鲁伊就去找赞塔布拉。' AS `dst`
    UNION ALL SELECT 'I can\'t help ya. Go talk ta Soratha if ya want mage trainin\'.' AS `src`, '我帮不了你。想学法术就去找索拉塔。' AS `dst`
    UNION ALL SELECT 'I can\'t help ya. Go talk ta Tunari if ya want priest trainin\'.' AS `src`, '我帮不了你。想学祭司之道就去找图纳里。' AS `dst`
    UNION ALL SELECT 'No snooping around, friend.$B$BIf you\'re looking to buy Crown holiday goods, you\'ll have to do it at the Lovely Merchant in the city.' AS `src`, '别到处打探，朋友。$B$B想买王冠节货物，得去城里的可爱商人那儿。' AS `dst`
    UNION ALL SELECT 'Lost?$b$bI am deeply disappointed, $n.$b$bThat ring was one of a kind, crafted out of the remnants of the armor of our fallen heroes and the purified metal from our enemy\'s blades.$b$bLet\'s not allow this to happen again.' AS `src`, '弄丢了？$b$b我深感失望，$n。$b$b那枚戒指独一无二，是用我们阵亡英雄的护甲残片和敌人刀剑提纯的金属铸成的。$b$b别再让这种事发生了。' AS `dst`
    UNION ALL SELECT 'Have you come to join the hunt, $N?' AS `src`, '你是来加入狩猎的吗，$N？' AS `dst`
    UNION ALL SELECT 'Be gone, $c.  I have no need of you in my hunt.' AS `src`, '走开，$c。我的狩猎不需要你。' AS `dst`
    UNION ALL SELECT 'Hey $gman:woman;, I\'m just tryin\' to get my slice of the pie.' AS `src`, '嘿，$g伙计：姑娘;，我只是想分一杯羹。' AS `dst`
    UNION ALL SELECT 'Turn away, $c.$B$BBefore the cataclysm hit, we found something.$B$BWe dug something up that should\'ve stayed buried.$B$BPray to whatever you believe in that the landslide was enough to keep it down...' AS `src`, '退开，$c。$B$B灾难降临之前，我们发现了些东西。$B$B我们挖出了本该永远埋在地底的东西。$B$B无论你信什么，都祈祷那场山崩足够把它压住吧……' AS `dst`
    UNION ALL SELECT 'You did it! We\'re saved!' AS `src`, '你做到了！我们得救了！' AS `dst`
    UNION ALL SELECT 'Thoth\'al amun Ree\'thael vormos! Vormos! Vormos!' AS `src`, '托斯阿尔·阿蒙·瑞埃瑟尔·沃莫斯！沃莫斯！沃莫斯！' AS `dst`
    UNION ALL SELECT 'The end of the world nears, $c. There is no need to despair. Hear what I say and what my brethren have to offer.' AS `src`, '世界末日近了，$c。不必绝望。听听我说的话，以及我的同胞能提供的东西。' AS `dst`
    UNION ALL SELECT 'Thank you for taking the time to help us test the Cataclysm content for World of Warcraft. \r\n\r\n\r\n\r\nWhere would you like to go?' AS `src`, '感谢你抽空帮我们测试《魔兽世界》大灾变内容。\n\n\n\n你想去哪儿？' AS `dst`
    UNION ALL SELECT '<The injured soldier\'s pained groans are somewhat distorted by the water.>' AS `src`, '<受伤士兵痛苦的呻吟在水声中有些失真。>' AS `dst`
    UNION ALL SELECT 'Wha - Where  am I? Are you one of them?' AS `src`, '什么——我在哪儿？你是他们中的一个吗？' AS `dst`
    UNION ALL SELECT 'Someone is using these beakers and alchemy tools to perform experiments with various types of submarine fuel.' AS `src`, '有人正用这些烧杯和炼金工具对各种潜艇燃料进行实验。' AS `dst`
    UNION ALL SELECT 'Several small samples of oil sit in front of you, along with an empty beaker.  The beaker looks like it can probably fit about five samples inside of it.$b$bWhat kind of oil will you take first?' AS `src`, '你面前放着几份小份的油样，以及一个空烧杯。这个烧杯看起来大概能装下五份样品。$b$b你想先取哪一种油？' AS `dst`
    UNION ALL SELECT 'What type of oil will you select next?' AS `src`, '你接下来要选哪种油？' AS `dst`
    UNION ALL SELECT 'You now have two samples of oil.  Which sample will you select next?' AS `src`, '你现在有两份油样。接下来选哪一份？' AS `dst`
    UNION ALL SELECT 'You now have three samples.  Which sample will you select next?' AS `src`, '你现在有三份样品。接下来选哪一份？' AS `dst`
    UNION ALL SELECT 'You have four samples, and only have room to test one more.  Which one will it be?' AS `src`, '你有四份样品，只还有空间再测一份。要选哪一个？' AS `dst`
    UNION ALL SELECT 'You have selected all five of your samples.' AS `src`, '你已选完全部五份样品。' AS `dst`
    UNION ALL SELECT 'You can use these beakers and alchemy tools to perform experiments with various types of submarine fuel.' AS `src`, '你可以用这些烧杯和炼金工具对各种潜艇燃料进行实验。' AS `dst`
    UNION ALL SELECT 'You have discovered a new type of bio-fuel!  Bring it to Engineer Hexascrub for testing.' AS `src`, '你发现了一种新型生物燃料！把它带给工程师赫克萨克拉布测试。' AS `dst`
    UNION ALL SELECT 'You have discovered a new type of bio-fuel!  Bring it to Fiasco Sizzlegrin for testing.' AS `src`, '你发现了一种新型生物燃料！把它带给菲亚斯科·西兹格林测试。' AS `dst`
    UNION ALL SELECT 'Cooking for the King is an honor, not a job.  Do you have time to help me on some errands?' AS `src`, '为国王下厨是荣誉，而不是差事。你有空帮我跑几趟腿吗？' AS `dst`
    UNION ALL SELECT 'Whaddya want?' AS `src`, '你想干吗？' AS `dst`
    UNION ALL SELECT 'Feeding a Horde army is no easy task.  I have lots to do, do you have time to help?' AS `src`, '供养一支部落大军可不是轻松活儿。我有一堆事要做，你有空帮忙吗？' AS `dst`
    UNION ALL SELECT 'Where to, buddy?' AS `src`, '去哪儿，伙计？' AS `dst`
    UNION ALL SELECT 'I can\'t do business with you, $c. Warchief\'s Orders.' AS `src`, '我没法跟你做生意，$c。这是酋长的命令。' AS `dst`
    UNION ALL SELECT 'Looks like I picked the wrong day to stop killin\' fel orcs.' AS `src`, '看来我挑错了停止屠杀恶魔兽人的日子。' AS `dst`
    UNION ALL SELECT 'What shall the Light teach you?' AS `src`, '圣光该教你些什么？' AS `dst`
    UNION ALL SELECT 'May the Sun\'s light protect you, $c.' AS `src`, '愿太阳之光护佑你，$c。' AS `dst`
    UNION ALL SELECT 'The Battle for Gilneas' AS `src`, '吉尔尼斯之战' AS `dst`
    UNION ALL SELECT 'You are not yet strong enough to enter The Battle for Gilneas. Return when you have gained more experience.' AS `src`, '你还不够强，无法进入吉尔尼斯之战。等你获得更多经验后再回来。' AS `dst`
    UNION ALL SELECT 'You are not yet strong enough to do battle in Twin Peaks. Return when you have gained more experience.' AS `src`, '你还不够强，无法在双子峰作战。等你获得更多经验后再回来。' AS `dst`
    UNION ALL SELECT 'Twin Peaks' AS `src`, '双子峰' AS `dst`
    UNION ALL SELECT 'Are you ready to train, warrior?' AS `src`, '你准备好接受训练了吗，战士？' AS `dst`
    UNION ALL SELECT 'I cannot help you with your training. Seek out a $c trainer.' AS `src`, '我没法指导你的训练。去找一位 $c 训练师吧。' AS `dst`
    UNION ALL SELECT 'Are you here to train, hunter?' AS `src`, '你是来接受训练的吗，猎人？' AS `dst`
    UNION ALL SELECT 'Are you here to train in Archaeology?' AS `src`, '你是来学习考古学的吗？' AS `dst`
    UNION ALL SELECT 'There are two: The Trader\'s Hall in the Trade District, and the Stormwind Auction House in the Dwarven District.' AS `src`, '有两处：贸易区的商人会堂，以及矮人区的暴风城拍卖行。' AS `dst`
    UNION ALL SELECT 'You\'ll find it in the northernmost part of the Dwarven District, near the Northern Landing.' AS `src`, '你会在矮人区最北端、北码头附近找到它。' AS `dst`
    UNION ALL SELECT 'There are two banks in the city: The Stormwind Counting House in the Trade District, and the Royal Bank of Stormwind in the Dwarven District.' AS `src`, '城里有两家银行：贸易区的暴风城金库，以及矮人区的暴风城皇家银行。' AS `dst`
    UNION ALL SELECT 'Stormwind\'s Royal Bank is in the northernmost corner of the Dwarven District, just inside the Northern Landing.' AS `src`, '暴风城皇家银行在矮人区最北角，就在北码头入口内。' AS `dst`
    UNION ALL SELECT 'Stormwind\'s two most popular inns are located in the Trade and Dwarven Districts: The Gilded Rose and The Golden Keg.' AS `src`, '暴风城最受欢迎的两家旅店位于贸易区和矮人区：镀金玫瑰旅店和金酒桶旅店。' AS `dst`
    UNION ALL SELECT 'The Golden Keg is in the northen part of the Dwarven District, right by the fountain.' AS `src`, '金酒桶旅店在矮人区北部，就在喷泉旁。' AS `dst`
    UNION ALL SELECT 'Stormwind has many points of interest, from the Deeprun Tram to Stormwind Keep.$B$BWhat were you looking for?' AS `src`, '暴风城有许多值得一看的地方，从矿道地铁到暴风城要塞。$B$B你想找什么？' AS `dst`
    UNION ALL SELECT 'There are stable masters in both Old Town and the Dwarven District.' AS `src`, '旧城区和矮人区都有驯兽师。' AS `dst`
    UNION ALL SELECT 'Byron Oakhorn can be found in earternmost Stormwind, through the gates at the back of Old Town.' AS `src`, '拜伦·橡角在最东边的暴风城，穿过旧城区后门的大门就能找到。' AS `dst`
    UNION ALL SELECT 'There are hunters training in Old Town\'s Command Center as well as in the Dwarven District.' AS `src`, '旧城区的指挥中心以及矮人区都有猎人在训练。' AS `dst`
    UNION ALL SELECT 'You can always find a handful of hunters just outside Old Town\'s east gate.' AS `src`, '在旧城区东门外总能找到一些猎人。' AS `dst`
    UNION ALL SELECT 'The Park...?$B$BIt\'s in ruins. Haven\'t you heard? The great dragon Deathwing soared over Stormwind and destroyed it in passing.$B$BNot sure why he didn\'t level everything, honestly, but we all thank the Light he didn\'t.' AS `src`, '公园……？$B$B已经成废墟了。你没听说吗？巨龙死亡之翼飞过暴风城，顺手就把它毁了。$B$B说实话，我不知道他为什么没把一切都夷平，不过我们都感谢圣光，他没有。' AS `dst`
    UNION ALL SELECT 'The keep is in northren Stormwind.$B$BJust follow the canals north and you\'ll eventually come across a drawbridge... that leads into the keep\'s courtyard.' AS `src`, '要塞在暴风城北部。$B$B顺着运河往北走，最终会看到一座吊桥……它通向要塞的庭院。' AS `dst`
    UNION ALL SELECT 'The prison? Why would you want to go there? It\'s in the center of the city, just northeast of the Mage Quarter.$B$BIf you\'re truly going there, be careful. I\'ve heard news of riots.' AS `src`, '监狱？你为什么要去那儿？它在城市中心，就在法师区东北方。$B$B你要是真要去，小心点。我听说有骚乱。' AS `dst`
    UNION ALL SELECT 'We\'ve been hearing reports of elemental disturbances around Azeroth for some time now. Our sources indicate that the phenomenon is not entirely natural, but we haven\'t quite been able to determine the source. We have some theories though, but nothing concrete.$B$BKeep your eye out for any suspicious elemental activity as you walk around.  If you find anything worthwhile, please let an Earthen Ring Emissary know. You can find us in any capital city.$B$BBe careful out there.  Trouble is brewing.' AS `src`, '我们这段时间一直收到艾泽拉斯各地元素扰动的报告。我们的消息来源表明这一现象并非完全自然，但我们还无法确定来源。我们有些推测，但都还不确定。$B$B走动时留意任何可疑的元素活动。如果你发现什么有价值的东西，请告知大地之环使者。在任意主城都能找到我们。$B$B在外小心。麻烦正在酝酿。' AS `dst`
    UNION ALL SELECT 'Denman Family Jewelers, between the northern Trade District and The Canals, should have everything you\'re looking for.' AS `src`, '登曼家族珠宝店，位于贸易区北部与运河区之间，应该有你想要的一切。' AS `dst`
    UNION ALL SELECT 'Harrison Jones teaches Archaeology in Stormwind Keep\'s Royal Library when not out in the field.' AS `src`, '哈里森·琼斯不在外勤时，会在暴风城要塞的皇家图书馆教授考古学。' AS `dst`
    UNION ALL SELECT 'Profession vendors can always be found near their respective trainers. Other sorts of vendors are scattered throughout Stormwind.$B$BWhat were you looking for?' AS `src`, '专业供应商通常都在各自训练师附近。其他各类商贩则散布在暴风城各处。$B$B你想找什么？' AS `dst`
    UNION ALL SELECT 'The Champions\' Hall is located in the southeastern end of Old Town.$B$BThe Honor and Conquest quartermasters can be found there.' AS `src`, '勇士大厅位于旧城区东南端。$B$B荣誉与征服军需官都在那里。' AS `dst`
    UNION ALL SELECT 'In the Command Center, just outside of Old Town\'s southeast gates, you\'ll find the quartermasters.' AS `src`, '在旧城区东南门外的指挥中心，你会找到军需官。' AS `dst`
    UNION ALL SELECT 'There are stables just beyond Old Town\'s southeast gates. You can find a riding trainer and a horse breeder there.' AS `src`, '旧城区东南门外就有马厩。那里有骑术训练师和养马人。' AS `dst`
    UNION ALL SELECT 'Do you know of the Gryphon Roost off the Trade District, where the Flight Master may be found?$B$BA pair of Wildhammer dwarves raises and sells gryphons there, and can even train you to ride the beasts.' AS `src`, '你知道贸易区外的狮鹫栖木吗？飞行管理员就在那儿。$B$B一对蛮锤矮人在那里饲养并出售狮鹫，甚至能教你骑乘这种生物。' AS `dst`
    UNION ALL SELECT 'You look exhausted. Is something wrong?' AS `src`, '你看起来很疲惫。出什么事了吗？' AS `dst`
    UNION ALL SELECT 'I can instruct you in blacksmithing as well as supply the necessary tools.$B$BHow may I help you?' AS `src`, '我可以教你锻造，也能供应必要的工具。$B$B我能帮你什么？' AS `dst`
    UNION ALL SELECT 'I can instruct you in herbalism as well as offer helpful supplies.$B$BHow may I help you?' AS `src`, '我可以教你草药学，也能提供有用的补给。$B$B我能帮你什么？' AS `dst`
    UNION ALL SELECT 'How may I be helpin\' ya, Child of de Earth?' AS `src`, '我能怎么帮你，大地之子？' AS `dst`
    UNION ALL SELECT 'Who knows what dark an\' horrid tings be gibberin\' in de outer darkness... tings dat\'d drive a soul mad ta see?$B$B-We- be knowin\'. An\' you\'ve come lookin\' ta know -more,- haven\'t ya?' AS `src`, '谁知道在外层黑暗中低语的，是怎样阴暗可怖的东西……那些东西看一眼就能让人发疯？$B$B-我们-知道。而你是来求知的--更多--，不是吗？' AS `dst`
    UNION ALL SELECT 'Greetin\'s, $N.  Are ya here ta be learnin\' of de Hidden Arts?' AS `src`, '问候你，$N。你是来学习隐秘技艺的吗？' AS `dst`
    UNION ALL SELECT '<Grunt>$b$bYou need something, $r?' AS `src`, '<咕哝>$b$b你需要什么吗，$r？' AS `dst`
    UNION ALL SELECT 'You be a LONG way from home, mon. Heh heh heh.\r\n\r\n\r\n\r\nWhat can I be helpin\' ya find?' AS `src`, '你离家可真是远啊，老兄。嘿嘿嘿。\n\n\n\n我能帮你找点什么？' AS `dst`
    UNION ALL SELECT 'Sorry, $c.$B$BI ain\'t believin\' ya got de right mind for graspin\' de nature of portal magic.' AS `src`, '抱歉，$c。$B$B我不信你有那个头脑去领悟传送魔法的本质。' AS `dst`
    UNION ALL SELECT 'De auction house and bank be at de top of de tall building in de middle of de valley, mon.$B$BLook for Ziji and Makavu.' AS `src`, '拍卖行和银行都在山谷中央那栋高楼的顶层，老兄。$B$B去找齐吉和马卡武。' AS `dst`
    UNION ALL SELECT 'You be wantin\' Sijambi, mon.$B$BShe be in de tall building in de middle of de valley.' AS `src`, '你要找的是西詹比，老兄。$B$B她就在山谷中央那栋高楼里。' AS `dst`
    UNION ALL SELECT 'Right outside de valley\'s inn, mon.$B$BIt be de tall building in de middle.' AS `src`, '就在山谷旅店外面，老兄。$B$B就是中间那栋高楼。' AS `dst`
    UNION ALL SELECT 'Which ya be lookin\' for?' AS `src`, '你要找哪一个？' AS `dst`
    UNION ALL SELECT 'You be lookin\' for Sesebi, mon.$B$BShe most often be sleepin\' under de tree by old Umbehto, de fisherman, lookin\' like a big ol\' tiger.' AS `src`, '你要找的是塞塞比，老兄。$B$B她多半睡在老渔夫乌姆贝托旁边那棵树下，看着像只大老虎。' AS `dst`
    UNION ALL SELECT 'Kuzari and Zanga are trainin\' headhunters on one of de small islets towards de southeast end of de valley, mon.' AS `src`, '库扎里和赞加在山谷东南端的一座小岛上训练猎头者，老兄。' AS `dst`
    UNION ALL SELECT 'Shadow-Walker Zuru can help ya.$B$BYou\'ll find him on de lowest floor of de taller building in de southeast.' AS `src`, '暗影行者祖鲁能帮你。$B$B你会在东南方那栋较高建筑的最底层找到他。' AS `dst`
    UNION ALL SELECT 'Ku\'nanji, de Night-Stalker, is who yer lookin\' for.$B$BHe be just north of de valley\'s central building.' AS `src`, '你要找的是夜行者库南吉。$B$B他就在山谷中央建筑的正北方。' AS `dst`
    UNION ALL SELECT 'Witch Doctor Umbu spends his time walkin\' about de valley, tendin\' to de people and elemental spirits alike.$B$BLook for him around de central building.' AS `src`, '巫医乌姆布总在山谷里走动，照料人们和元素之灵。$B$B在中央建筑附近找他。' AS `dst`
    UNION ALL SELECT 'You be crazy, mon, meddlin\' with dat bad mojo. But I ain\'t one ta stop ya.$B$BUnjari Feltongue is in de taller building in de southeast, past de shadow priest\'s shrine.' AS `src`, '你疯了，老兄，竟去碰那种恶咒。不过我可不打算拦你。$B$B乌恩贾里·费尔舌在东南方那栋较高的建筑里，过了暗影祭司的神龛就是。' AS `dst`
    UNION ALL SELECT 'Zamja be de best cook in Orgrimmar, mon.$B$BYou can find her just south of de valley\'s central building. Batamsi sells de food Zamja makes, too, if ya just be hungry.' AS `src`, '扎姆贾是奥格瑞玛最好的厨子，老兄。$B$B你可以在山谷中央建筑正南方找到她。你要是只是饿了，巴塔姆西也卖扎姆贾做的食物。' AS `dst`
    UNION ALL SELECT 'Jandi and Zeal\'aya work from a hut just north of de valley\'s central building.$B$BDey can help ya wit\' whatever ya need, mon.' AS `src`, '詹迪和泽尔阿雅在山谷中央建筑正北方的一间小屋里干活。$B$B你需要什么他们都能帮你，老兄。' AS `dst`
    UNION ALL SELECT 'Old Umbehto be on a lil\' islet east of de valley\'s central buildin\'.' AS `src`, '老乌姆贝托在山谷中央建筑东边的一座小岛上。' AS `dst`
    UNION ALL SELECT 'Huju and Xen\'to can take care of ya.$B$BFind dem in de valley\'s central building, mon.' AS `src`, '胡朱和森托能照料你。$B$B去山谷的中央建筑找他们，老兄。' AS `dst`
    UNION ALL SELECT 'Xan\'tish and his snakes are slitherin\' around de valley\'s central building, mon.' AS `src`, '桑提什和他的蛇在山谷中央建筑周围游走，老兄。' AS `dst`
    UNION ALL SELECT 'These are grave times for Azeroth, $n.' AS `src`, '对艾泽拉斯来说这是严峻的时刻，$n。' AS `dst`
    UNION ALL SELECT 'I cannot promise that your rest will be peaceful, $c.  These orcs do not know when to quit.' AS `src`, '我无法保证你的安息会平静，$c。这些兽人不知道什么叫停手。' AS `dst`
    UNION ALL SELECT 'You and your coin are -always- welcome here.' AS `src`, '你和你的钱在这里永远受欢迎。' AS `dst`
    UNION ALL SELECT 'She\'s hung up in the debris and I\'ve lost steam pressure. This terrain is murder!$B$BCan you get us out of this?' AS `src`, '她被卡在残骸里，而我又没了蒸汽压力。这地形简直要命！$B$B你能把我们弄出去吗？' AS `dst`
    UNION ALL SELECT 'No offense, but you don\'t look like you could shoot the broad side of a pack kodo.$B$BHow about we stop wastin\' each other\'s time and you go find the right trainer.' AS `src`, '别见怪，可你看起来连科多兽的侧面都射不中。$B$B咱们别互相浪费时间了，你去找对的训练师吧。' AS `dst`
    UNION ALL SELECT 'Yo. Up for a little target practice?' AS `src`, '哟。想来练练打靶吗？' AS `dst`
    UNION ALL SELECT 'Hey there, $N. Here for a lesson? I ain\'t got all day...' AS `src`, '嘿，$N。来上课的？我可没一整天工夫……' AS `dst`
    UNION ALL SELECT 'Hey, it ain\'t MY fault ya didn\'t learn proper spellcraft.\r\n\r\n\r\n\r\nGo pester a $c trainer, yeah?' AS `src`, '嘿，你没学到正经的施法技艺，可不是-我-的错。\n\n\n\n去烦一位 $c 训练师吧，行不？' AS `dst`
    UNION ALL SELECT 'I heard ya comin\' a league away, mon. Maybe ya need some more trainin\'?' AS `src`, '我在一里格之外就听见你来了，老兄。也许你还得多练练？' AS `dst`
    UNION ALL SELECT 'What?  I look like a $c to you?$B$BGet outta here, will ya?' AS `src`, '什么？你觉得我像 $c 吗？$B$B出去吧，行不行？' AS `dst`
    UNION ALL SELECT 'You need somethin\'?$B$BToo bad. I got nothin\' for ya, $c.' AS `src`, '你需要点什么？$B$B真可惜。我这儿没你要的东西，$c。' AS `dst`
    UNION ALL SELECT '"Controlling the Elements for Fun and Profit."$B$BThat\'s what it\'s all about, am I right?  Let\'s get ta work.' AS `src`, '《掌控元素：寓乐于利》。$B$B这不就是全部嘛，对吧？开工吧。' AS `dst`
    UNION ALL SELECT 'Look. You don\'t even WANNA know the sorta stuff I could teach ya.$B$BSeriously. It\'d melt yer brain. Go play nice somewhere else.' AS `src`, '听着。你根本-不-想知道我能教你些什么。$B$B说真的。那会把你的脑子熔掉。去别处好好玩吧。' AS `dst`
    UNION ALL SELECT 'You gotta love fel energy: Cheap, renewable, and guaranteed to blow things up.$B$BSure, you risk losin\' your eternal will to Unimaginable Horrors from Beyond Time and Space, but hey, risk versus reward!$B$BNow, what did you wanna see me about, hmmm?' AS `src`, '你得爱上邪能：便宜、可再生，而且保证能把东西炸飞。$B$B当然，你可能会失去永恒的意志，被来自时空之外难以想象的恐怖吞噬，不过嘛，风险与回报！$B$B现在，你找我有什么事，嗯？' AS `dst`
    UNION ALL SELECT 'If you\'re looking for an Arcane Reforger, there is a highborne mage inside the enchanting shop just outside the Mage District.' AS `src`, '你要找奥术重铸师的话，法师区外面的附魔店里有位上层精灵法师。' AS `dst`
    UNION ALL SELECT 'Poor dear, you must be exhausted.$B$BThere\'s food and drink, if you like, and it\'s safe to rest here.' AS `src`, '可怜的亲爱的，你一定累坏了。$B$B这儿有食物和饮料，想用就用，在这儿休息很安全。' AS `dst`
    UNION ALL SELECT 'Looking for something to eat, $c?$B$BOr just a place to rest your weary bones for a while?' AS `src`, '想找点吃的，$c？$B$B还是只想找个地方歇歇你疲惫的骨头？' AS `dst`
    UNION ALL SELECT 'Yo.$B$BYou here to stable your pets, or lookin\' for a lost companion?' AS `src`, '哟。$B$B你是来寄存宠物的，还是在找一个走失的伙伴？' AS `dst`
    UNION ALL SELECT 'Yo.$B$BYou lookin\' for a lost companion?' AS `src`, '哟。$B$B你是在找一个走失的伙伴？' AS `dst`
    UNION ALL SELECT 'So... thirsty...' AS `src`, '好……渴……' AS `dst`
    UNION ALL SELECT 'This dwarf\'s body is severely battered. The Twilight\'s Hammer must take pleasure in their killing.' AS `src`, '这名矮人的遗体被严重损毁。暮光之锤一定很享受他们的杀戮。' AS `dst`
    UNION ALL SELECT 'Your time is coming to an end.' AS `src`, '你的时限快到了。' AS `dst`
    UNION ALL SELECT 'After the fall of the Burning Blade Clan, we blademasters swore to free ourselves and our people from demonic control.$B$BThis may be done, but my honor remains unsatisfied.$B$BI shall fight for the Horde - and train other warriors to do so - until I die gloriously in battle. This is the only path I may tread.$B$BSo. Are you ready to train?' AS `src`, '燃刃氏族覆灭之后，我们剑圣发誓要让自己和族人摆脱恶魔的控制。$B$B这也许做到了，但我的荣誉仍未满足。$B$B我将为部落而战——并训练其他战士如此——直到我在战斗中光荣死去。这是我唯一能走的道路。$B$B那么。你准备好接受训练了吗？' AS `dst`
    UNION ALL SELECT 'Guarding the bank and treasures of the Horde is far more satisfying than dispensing coins and trade goods from inside a cage of iron.$B$BI would not exchange places with one of those quill-pushing goblins for a moment.' AS `src`, '守卫部落的银行与宝藏，远比在铁笼里分发钱币和货物来得满足。$B$B我可一刻也不愿和那些推笔杆子的地精换位置。' AS `dst`
    UNION ALL SELECT 'Gathering professions allow you to acquire raw materials used by production professions: gathering herbs; mining ore, stone, and jewels; or skinning beasts for their hides.\r\n\r\n\r\n\r\nYou can either support a related production profession with gathering, or simply sell the raw materials on the auction house.' AS `src`, '采集专业让你获得生产专业所需的原材料：采集草药；开采矿石、石头和宝石；或者剥取野兽的皮革。\n\n\n\n你可以用采集来支持相关的生产专业，也可以干脆把原材料放到拍卖行出售。' AS `dst`
    UNION ALL SELECT 'Production professions allow you to turn raw materials into items that you can use yourself, give to companions, or sell at an auction house.\r\n\r\n\r\n\r\nThey are often paired with a gathering profession so that you can gather your own raw materials, but it is possible to simply buy materials on the auction house.' AS `src`, '生产专业让你把原材料制成物品，用于自己使用、送给同伴，或在拍卖行出售。\n\n\n\n它们常与采集专业搭配，这样你就可以自己采集原料，当然也可以直接在拍卖行购买材料。' AS `dst`
    UNION ALL SELECT 'Herbalism allows you to locate and gather herbs from the wild. These can be sold at the auction house or used to support the Alchemy or Inscription professions.\r\n\r\n\r\n\r\nSkilled herbalists can also use their knowledge of the earth to heal themselves.' AS `src`, '草药学让你能在野外找到并采集草药。草药可以卖到拍卖行，或用于支持炼金术与铭文专业。\n\n\n\n熟练的草药师还能运用对大地知识的了解为自己治疗。' AS `dst`
    UNION ALL SELECT 'Mining allows you to locate and mine ore, minerals and stone from mining nodes in the wilderness and underground. These can be sold at the auction house or used to support the Blacksmithing, Engineering, or Jewelcrafting professions.\r\n\r\n\r\n\r\nSkilled miners also become tough and gain increased Stamina.\r\n\r\n\r\n\r\nYou\'ll need a Mining Pick in order to mine; this can be purchased from trade or Mining vendors.' AS `src`, '采矿让你能在野外和地下的矿点找到并开采矿石、矿物与石头。它们可以卖到拍卖行，或用于支持锻造、工程学或珠宝加工专业。\n\n\n\n熟练的矿工还会变得强壮，获得额外的耐力。\n\n\n\n采矿需要一把矿工锄；可从贸易或采矿供应商处购买。' AS `dst`
    UNION ALL SELECT 'Skinning allows you to remove and prepare the hides from slain creatures. These can be sold at the auction house or used to support the Leatherworking profession.\r\n\r\n\r\n\r\nSkilled Skinners also become masters of anatomy, increasing their chances to critically hit a target.\r\n\r\n\r\n\r\nYou\'ll need a Skinning Knife in order to skin creatures; this can be purchased from trade or Leatherworking vendors.' AS `src`, '剥皮让你能从被杀死的生物身上取下并处理皮革。皮革可卖到拍卖行，或用于支持制皮专业。\n\n\n\n熟练的剥皮师还会成为解剖大师，提高对目标的暴击几率。\n\n\n\n剥皮需要一把剥皮小刀；可从贸易或制皮供应商处购买。' AS `dst`
    UNION ALL SELECT 'Alchemy allows you to use herbs and other materials to create a wide variety of useful elixirs, potions, oils, flasks and cauldrons. You\'ll also gain greater, longer-lasting benefits when using your own elixirs and flasks.\r\n\r\n\r\n\r\nHighly skilled alchemists may also transmute elemental materials and certain minerals for use by other production professions.\r\n\r\n\r\n\r\nAlchemy pairs well with Herbalism as it allows you to gather your own herbs.' AS `src`, '炼金术让你能用草药和其他材料制作各种有用的药剂、药水、油、合剂和大锅。使用自己制作的药剂和合剂时，你还会获得更强、更持久的效果。\n\n\n\n技艺高超的炼金师还能转化元素材料和某些矿物，供其他生产专业使用。\n\n\n\n炼金术与草药学搭配很好，因为你可以自己采集草药。' AS `dst`
    UNION ALL SELECT 'Blacksmithing allows you to forge items from metals, minerals and stones: melee weapons, mail and plate heavy armor, raw materials used by other production professions, and upgrades to pieces of equipment such as sharpening stones and shield spikes.\r\n\r\n\r\n\r\nHighly skilled blacksmiths can add a gem slot to their own bracers and gloves, as well as to their own or other\'s belts. These gem slots may then be filled with magical gems that make the gemmed item more powerful.\r\n\r\n\r\n\r\nBlacksmithing pairs well with Mining as it allows you to gather your own ore and minerals.' AS `src`, '锻造让你用金属、矿物和石头打造物品：近战武器、锁甲与板甲重甲、其他生产专业使用的原材料，以及磨刀石、盾刺之类的装备强化件。\n\n\n\n技艺高超的铁匠还能给自己的护腕和手套、以及自己或他人的腰带加装宝石插槽。这些插槽随后可镶入魔法宝石，使装备更强大。\n\n\n\n锻造与采矿搭配很好，因为你可以自己采集矿石和矿物。' AS `dst`
    UNION ALL SELECT 'Enchanting allows you to enchant items with a wide variety of beneficial effects, as well as disenchant items and create magical wands and oils.\r\n\r\n\r\n\r\nHighly skilled enchanters can even enchant their own rings, which no one else may do.\r\n\r\n\r\n\r\nMost raw materials for Enchanting must be gathered via disenchanting, a process which destroys the disenchanted item. For this reason the profession pairs well with Tailoring, as you can disenchant the magical Tailoring items you create for raw materials.\r\n\r\n\r\n\r\nEnchanters may also place enchantments upon vellum, which allows the enchantment to be sold or saved for later use. Vellum and other useful Enchanting materials may be purchased from Enchanting vendors.' AS `src`, '附魔让你能为物品附上各种有益效果，也能分解物品，制作魔杖和魔油。\n\n\n\n技艺高超的附魔师甚至能给自己的戒指附魔，这是别人做不到的。\n\n\n\n附魔的大部分原材料必须通过分解获得，而分解会摧毁被分解的物品。因此这个专业与裁缝搭配很好——你可以分解自己制作的裁缝魔法物品来获得原料。\n\n\n\n附魔师还能把附魔写在附魔羊皮纸上，这样附魔就能出售或留待以后使用。羊皮纸和其他有用的附魔材料可从附魔供应商处购买。' AS `dst`
    UNION ALL SELECT 'Engineering allows you to construct a wide variety of useful, amazing, and just plain weird items like rifles and scopes, motorcycles, and mechanical squirrels. However, many of these are only usable by yourself or other engineers, such as special goggles, mechanical additions to belts, boots, gloves and cloaks, and flying machines.\r\n\r\n\r\n\r\nMost raw Engineering materials are metals gathered by Mining, so the two professions pair well.\r\n\r\n\r\n\r\nMany creations require the use of a Blacksmith Hammer; this and other necessary materials, such as gun stocks or flux, may be purchased from trade or Engineering vendors.' AS `src`, '工程学让你能制造各种有用、惊人、乃至纯粹古怪的东西，比如步枪和瞄准镜、摩托车和机械松鼠。不过其中许多只能自己或其他工程师使用，例如特殊护目镜、腰带、靴子、手套和披风的机械附加装置，以及飞行器。\n\n\n\n工程学的大部分原材料是采矿所得的金属，所以这两个专业搭配很好。\n\n\n\n许多造物需要使用铁匠锤；铁匠锤和枪托、助熔剂等其他必需材料可从贸易或工程学供应商处购买。' AS `dst`
    UNION ALL SELECT 'Inscription allows you to create magical scrolls, glyphs, off-hand tomes, Darkmoon cards, and even recipes for other professions.\r\n\r\n\r\n\r\nMany raw materials for Inscription come from milling herbs gathered by Herbalism, so the two professions pair well.\r\n\r\n\r\n\r\nYou\'ll need to a Virtuoso Inking Set for inscribing things; this and other necessary materials, such as parchment, may be purchased from Inscription vendors.' AS `src`, '铭文让你能制作魔法卷轴、雕文、副手书籍、暗月卡片，甚至其他专业的配方。\n\n\n\n铭文的许多原材料来自研磨草药学采集的草药，所以这两个专业搭配很好。\n\n\n\n铭刻物品需要一套铭文大师的工具；它和羊皮纸等其他必需材料可从铭文供应商处购买。' AS `dst`
    UNION ALL SELECT 'Jewelcrafting allows you to fashion magical rings, amulets, and trinkets as well as cut gems.\r\n\r\n\r\n\r\nThe gems used in Jewelcrafting may be purchased or acquired via Prospecting from ore gathered by Mining; for this reason the two professions pair well.\r\n\r\n\r\n\r\nMost Jewelcrafting designs also require a Jeweler\'s Kit while more advanced creations require a Simple Grinder; these may be purchased from Jewelcrafting vendors.' AS `src`, '珠宝加工让你能制作魔法戒指、项链和饰品，也能切割宝石。\n\n\n\n珠宝加工所用的宝石可以购买，也可通过探矿从采矿所得的矿石中获得；因此这两个专业搭配很好。\n\n\n\n大多数珠宝设计还需要珠宝工具，更高级的造物则需要简易研磨器；这些可从珠宝加工供应商处购买。' AS `dst`
    UNION ALL SELECT 'Leatherworking allows you to fashion armor, cloaks, armor-reinforcing kits, and other similar items from leather, hides, and scales. Other materials required for leatherworking can be purchased at trade and Leatherworking vendors.\r\n\r\n\r\n\r\nLeatherworking pairs well with Skinning as it allows you to gather your own raw materials; other necessary items, such as threads and dyes, can be purchased from trade or Leatherworking vendors.\r\n\r\n\r\n\r\nHighly skilled leatherworkers can also enforce their bracers and leg armor.' AS `src`, '制皮让你能用皮革、兽皮和鳞片制作护甲、披风、护甲强化套件及类似物品。制皮所需的其他材料可在贸易和制皮供应商处购买。\n\n\n\n制皮与剥皮搭配很好，因为你可以自己采集原材料；线、染料等其他必需物品可从贸易或制皮供应商处购买。\n\n\n\n技艺高超的制皮师还能强化自己的护腕和腿部护甲。' AS `dst`
    UNION ALL SELECT 'Tailoring allows you to fashion armor, cloaks, clothing, bags, spellthread, and other similar items from various types of cloth, which can be purchased or taken from slain humanoid enemies. Additional necessary materials such as threads and dyes can be purchased from trade or Tailoring vendors.\r\n\r\n\r\n\r\nHighly skilled tailors can also upgrade their cloaks with magical embroidery.\r\n\r\n\r\n\r\nEnchanters are often tailors as well, since they can disenchant the magical items they create.' AS `src`, '裁缝让你能用各种布料制作护甲、披风、衣物、背包、法线及类似物品，布料可以购买，也可从被杀死的人形敌人身上取得。线、染料等其他必需材料可从贸易或裁缝供应商处购买。\n\n\n\n技艺高超的裁缝还能用魔法刺绣强化自己的披风。\n\n\n\n附魔师往往也是裁缝，因为他们能分解自己制作的魔法物品。' AS `dst`
    UNION ALL SELECT 'Hey there, good lookin\'.' AS `src`, '嘿，美人儿。' AS `dst`
    UNION ALL SELECT 'For too long we have ignored the secrets of the Arcane.$B$BAre you here to learn, as well?' AS `src`, '太久以来，我们一直忽视奥术的秘密。$B$B你也是来学习的吗？' AS `dst`
    UNION ALL SELECT 'You too are a student of the arcane, yes?$B$BI can teach you about portal magic, if you wish to learn.' AS `src`, '你也是奥术的学徒，对吧？$B$B如果你愿意学，我可以教你传送门魔法。' AS `dst`
    UNION ALL SELECT 'I\'m afraid I cannot help you, $r, but I am sure Khaelyn Steelwing can.' AS `src`, '恐怕我帮不了你，$r，但我确信凯琳·钢翼能帮你。' AS `dst`
    UNION ALL SELECT 'I\'m afraid I cannot assist you, $r, but I am certain Georgia can.' AS `src`, '恐怕我无法帮你，$r，但我确信乔治亚能。' AS `dst`
    UNION ALL SELECT 'Through this portal, Tol Barad awaits.' AS `src`, '穿过这道传送门，托尔巴拉德在等着你。' AS `dst`
    UNION ALL SELECT 'The Earthen Ring have set up portals to various regions of the world on a small lake islet northwest of Stormwind Keep.\r\n\r\nThere are representatives from the Baradin Wardens there as well, offering transport to Tol Barad.' AS `src`, '大地之环在暴风城要塞西北的一个小湖岛上设置了通往世界各地区的传送门。\n\n那里还有巴拉丁守望者的代表，提供前往托尔巴拉德的交通。' AS `dst`
    UNION ALL SELECT 'The Earthen Ring have set up portals to various regions of the world on the cliffs north of the zeppelin towers.\r\n\r\n\r\n\r\nThere are representatives from Hellscream\'s Reach there as well, offering transport to Tol Barad.' AS `src`, '大地之环在飞艇塔北边的悬崖上设置了通往世界各地区的传送门。\n\n\n\n那里还有地狱咆哮之手的代表，提供前往托尔巴拉德的交通。' AS `dst`
    UNION ALL SELECT 'If you\'re looking for an Arcane Reforger, there is a blood elf mage inside the Drag\'s enchanting shop, Godan\'s Runeworks.' AS `src`, '你要找奥术重铸师的话，暗影裂口的附魔店戈丹符文工坊里有位血精灵法师。' AS `dst`
    UNION ALL SELECT '<The Mullan Gryphon Rider stays still, eyes locked forward, not acknowledging your presence.>' AS `src`, '<穆兰狮鹫骑士一动不动，目光直视前方，不理会你的存在。>' AS `dst`
    UNION ALL SELECT 'Duglas send you over to get roughed up?' AS `src`, '是杜格拉斯派你来挨揍的吗？' AS `dst`
    UNION ALL SELECT 'You\'ll want to find Adam Hossack. He\'s got an office in the southern Mage Quarter along the inner ring.$B$BIf he\'s not out exploring, he\'ll likely be there.' AS `src`, '你要找亚当·霍萨克。他在法师区南侧内环有间办公室。$B$B如果他没有外出探索，多半就在那儿。' AS `dst`
    UNION ALL SELECT 'Dedlow Wormwood\'s the corpse you want. He\'s usually around the south end of town.' AS `src`, '你要找的尸体是戴德洛·沃姆伍德。他通常在镇子南边一带出没。' AS `dst`
    UNION ALL SELECT 'This orc is severely injured.' AS `src`, '这名兽人受了重伤。' AS `dst`
    UNION ALL SELECT 'Who are you?' AS `src`, '你是谁？' AS `dst`
    UNION ALL SELECT 'Have you come for training, hunter?' AS `src`, '你是来接受训练的吗，猎人？' AS `dst`
    UNION ALL SELECT 'The good Doktor Professor Ironpants may be found in the Hall of Explorers.' AS `src`, '好医生钢铁裤教授在探险者大厅。' AS `dst`
    UNION ALL SELECT 'Ye\'ll find an Arcane Reforger in Gimble\'s shop, Thistlefuzz Arcanery, right by the Gryphon Master at The Great Forge.$B$BHe\'s one o\' them long-lost Highborne elves, but he\'ll do ye right.' AS `src`, '你会在金布尔店里、蓟绒秘术店找到奥术重铸师，就在大熔炉的狮鹫管理员旁边。$B$B他是那种久已失传的上层精灵，不过他办事靠得住。' AS `dst`
    UNION ALL SELECT 'There is a blood elf in the Valley of Strength\'s central fortress, part of a delegation from Silvermoon: Belloc. He is who you want.' AS `src`, '力量谷中央堡垒里有一位血精灵，是来自银月城的使团成员：贝洛克。他就是你要找的人。' AS `dst`
    UNION ALL SELECT 'The mages may be found in Cleft of Shadow.  There are two entrances: One between the valleys of Strength and Wisdom, and the other in The Drag.' AS `src`, '法师们在暗影裂口。那里有两个入口：一个在力量谷与智慧谷之间，另一个在暗影裂口。' AS `dst`
    UNION ALL SELECT 'There is a scholar, Arunel, who can assist you.  You will find him in the Temple of the Moon, often conversing with one of the returned Highborne.' AS `src`, '有一位学者阿鲁内尔可以帮你。你会在月神殿找到他，他常与一位回归的上层精灵交谈。' AS `dst`
    UNION ALL SELECT 'Do I know you? No? Welcome to the Twilight\'s Hammer.' AS `src`, '我认识你吗？不认识？欢迎来到暮光之锤。' AS `dst`
    UNION ALL SELECT 'Otoh Greyhide spends much of time in the Hall of Elders on the Elder Rise.  Seek him out there, and he will help you.' AS `src`, '奥托灰鬃大部分时间都在长者高地的长者大厅。去那儿找他，他会帮你。' AS `dst`
    UNION ALL SELECT 'You will find the Sunwalker\'s Lodge on Hunter\'s Rise.' AS `src`, '你会在猎手高地找到日行者小屋。' AS `dst`
    UNION ALL SELECT 'The city\'s Arcane Reforger, Enchantress Fira, will be able to help you.  She is most often found with Sedana and her enchanter\'s apprentices, off the Court of the Sun.' AS `src`, '这座城的奥术重铸师、附魔师菲拉能帮你。她多半和塞达娜以及她的附魔学徒们在一起，就在太阳庭院外。' AS `dst`
    UNION ALL SELECT 'Boduro the Seeker can often be found in the merchant\'s bazaar within the Lower City. I would look for him there.' AS `src`, '探求者博杜罗常在贫民窟的商人集市。我建议你去那儿找他。' AS `dst`
    UNION ALL SELECT 'The high elf mage and scholar Dariness is the city\'s most learned archaeologist... and the most sociable.$B$BShe can often be found in the Legerdemain Lounge, just north of the city\'s center, enjoying the atmosphere or discussing her wild adventures with the proprieters and patrons both.' AS `src`, '高等精灵法师兼学者达琳妮丝是这座城市最有学问的考古学家……也是最健谈的。$B$B你常能在城市中心正北的诡术师酒廊找到她，她在那儿享受气氛，或与店主和顾客谈论她的冒险经历。' AS `dst`
    UNION ALL SELECT 'You lookin\' for trainin\'? No can do. I ain\'t your guy.' AS `src`, '你想学点什么？不行。我不是你要找的人。' AS `dst`
    UNION ALL SELECT 'You lookin\' to train up, bruiser?' AS `src`, '你想训练一下吗，壮汉？' AS `dst`
    UNION ALL SELECT 'Now that we have captured this wretched isle, we need to do some work to get it into shape.  Can you help us out $n?' AS `src`, '既然我们已经夺取了这座可恶的岛屿，就得做些事让它像个样子。你能帮我们吗，$n？' AS `dst`
    UNION ALL SELECT 'I am not a fan of that d-block place everyone keeps talking about it.  We do have some tasks that must be completed before we can use it though.' AS `src`, '我不喜欢大家老在说的那个 D 区。不过在我们能用它之前，确实有些任务必须完成。' AS `dst`
    UNION ALL SELECT 'I assume you have heard of the hole by now, $r.  If not, you are going to know a whole lot about it soon.' AS `src`, '我猜你现在已经听说过那个窟窿了，$r。要是还没，你很快就会知道得一清二楚。' AS `dst`
    UNION ALL SELECT 'Welcome to Tol Barad, $c.  Time\'s a wastin\' so let\'s get to work.' AS `src`, '欢迎来到托尔巴拉德，$c。时间不等人，开工吧。' AS `dst`
    UNION ALL SELECT 'It looks like the cultists had their eye on the druids!$B$BYou can see Wildheart Point through the swirling portal. Stepping through it will take you on a one-way trip back to the camp.$B$BOnce your business here is finished, this would be a good way to make a quick exit.' AS `src`, '看来教徒们的目标是德鲁伊们！$B$B你能透过旋涡状的传送门看到野性之心据点。走进去会把你单程送回营地。$B$B等你这边的事办完，这是个快速离开的好办法。' AS `dst`
    UNION ALL SELECT 'Alsudar the Bastion and the other warrior trainers may be found overlooking Farstriders\' Square, from near the foundry.' AS `src`, '堡垒阿尔苏达和其他战士训练师在远行者广场附近、铸造厂旁的高处。' AS `dst`
    UNION ALL SELECT 'Lot\'s to be done around here, $r.  Are you ready to help?' AS `src`, '这附近有一堆事要做，$r。你准备好帮忙了吗？' AS `dst`
    UNION ALL SELECT 'Welcome to baradin base camp.  I know it does not look like much now, but with a little hard work we can whip this place into shape.' AS `src`, '欢迎来到巴拉丁基地。我知道现在看起来不怎么样，但只要下点苦功，我们就能把这儿整治得像样。' AS `dst`
    UNION ALL SELECT 'Seems like we never run out of things to do around here.  New orders arrive every day at 3am, it\'s really strange.' AS `src`, '看来我们这儿的活儿永远干不完。每天凌晨三点都有新命令送到，真是太奇怪了。' AS `dst`
    UNION ALL SELECT 'The horde have been relentless out here.  Feels like we are fighting two battles at one time.' AS `src`, '部落在这边毫不留情。感觉我们同时在打两场仗。' AS `dst`
    UNION ALL SELECT 'I wish I could make you a deal, partner - I really do - but you\'ll need to be exalted with the Bilgewater Cartel, first.' AS `src`, '我真希望能跟你做笔交易，伙计——真的——不过你得先和锈水财阀达到崇拜才行。' AS `dst`
    UNION ALL SELECT 'Yo! I\'m Kall Worthaton, Bilgewater Trikes.$B$BGo ahead, look over the lot. Pick out the trike that you REALLY want!$B$BA trike that\'s a blast to ride... a trike that\'s dangerous and death-defying... a trike you can be PROUD of!$B$BYou let me know when you see it, and we\'ll make a deal.' AS `src`, '哟！我是卡尔·沃萨顿，锈水三轮车。$B$B来吧，看看这一批。挑出你-真正-想要的那辆三轮车！$B$B一辆骑起来超爽的三轮车……一辆危险又玩命的三轮车……一辆让你-自豪-的三轮车！$B$B你看中了就告诉我，咱们谈笔交易。' AS `dst`
    UNION ALL SELECT 'Welcome, my $g brother : sister;.  If you are here to train, then I would be delighted to train you.$B$BWe are the preservers of the balance, now and forever, with Malfurion watching over us.  Never forget this.' AS `src`, '欢迎，我的 $g兄弟：姐妹;。如果你是来接受训练的，我很乐意训练你。$B$B我们是平衡的守护者，现在如此，永远如此，玛法里奥守护着我们。永远不要忘记这一点。' AS `dst`
    UNION ALL SELECT 'Our master Malfurion has returned from the Dreaming, $c.  His is the light of a beacon that shows the way for us, and we must do everything in our power to preserve that light.' AS `src`, '我们的导师玛法里奥已从梦境归来，$c。他就像一座灯塔的光，为我们指引道路，我们必须竭尽全力守护那道光。' AS `dst`
    UNION ALL SELECT 'I cannot help you, $c.' AS `src`, '我帮不了你，$c。' AS `dst`
    UNION ALL SELECT 'My apologies, $c, but the arcane secrets of the Highborne will forever remain secrets to you.' AS `src`, '抱歉，$c，但上层精灵的奥术秘密对你永远都是秘密。' AS `dst`
    UNION ALL SELECT 'The magic of today pales in comparison to that of millennia past. Still, we Highborne know much of the arcane. Are you ready to learn?' AS `src`, '如今的魔法与千年前相比黯然失色。不过，我们上层精灵仍深谙奥术。你准备好学习了吗？' AS `dst`
    UNION ALL SELECT 'Halbin Frosthammer, from the Wildhammer clan, can be found in Thunderbrew Distillery.  He can help teach ya the ways of the shaman.' AS `src`, '蛮锤氏族的哈尔宾·霜锤在雷酒酿酒厂。他能教你萨满之道。' AS `dst`
    UNION ALL SELECT 'Look for The Wyvern\'s Tail, just outside the Hall of the Brave.' AS `src`, '找“飞龙之尾”旅店，就在勇者大厅外面。' AS `dst`
    UNION ALL SELECT 'It\'s across the bridge from the gate to The Drag. Listen for the sound of shouting goblins.' AS `src`, '它就在从大门通往暗影裂口的桥对面。听听地精们的叫喊声就知道了。' AS `dst`
    UNION ALL SELECT 'The Valley of Honor\'s bank is just before the gate to The Drag.' AS `src`, '荣誉谷的银行就在通往暗影裂口的门之前。' AS `dst`
    UNION ALL SELECT 'To reach the Rut\'theran Ferry, you will need to travel to Darnassus and take the portal to Rut\'theran Village at the base of Teldrassil.' AS `src`, '要乘坐鲁瑟兰渡船，你需要前往达纳苏斯，然后从泰达希尔山脚的传送门前往鲁瑟兰村。' AS `dst`
    UNION ALL SELECT 'There is a Highborne archmage visiting the city\'s Enchanting trainer. You can have your items reforged there.' AS `src`, '有一位上层精灵大法师正在拜访城里的附魔训练师。你可以在那里重铸你的物品。' AS `dst`
    UNION ALL SELECT 'Which one?' AS `src`, '哪一个？' AS `dst`
    UNION ALL SELECT 'Choose a destination.' AS `src`, '请选择一个目的地。' AS `dst`
    UNION ALL SELECT 'I will mark the location upon your map.' AS `src`, '我会在地图上标出位置。' AS `dst`
    UNION ALL SELECT 'Well met, $c.  My advice to you is this: As you travel the world, be wary of magic for it will burn the untrained.' AS `src`, '幸会，$c。我给你的建议是：周游世界时，要提防魔法，它会灼伤未经训练的人。' AS `dst`
    UNION ALL SELECT 'Weary of one of your demonic charges? Hoping for one with a more pleasing name?\r\n\r\n\r\n\r\nFor a price, I can assist you in the obliteration of a current minion so that you may summon an entirely new one...' AS `src`, '厌倦了你的某个恶魔仆从？希望换一个名字更顺耳的？\n\n\n\n只要付钱，我就能帮你消灭现有的仆从，好让你召唤一个全新的……' AS `dst`
    UNION ALL SELECT 'This teleportation device appears to have been used recently to teleport various goods deeper into the mine.' AS `src`, '这个传送装置似乎最近被用来把各种货物传送到矿井深处。' AS `dst`
    UNION ALL SELECT 'Though many flames are fought over, extinguished and re-lit, all are welcome to show honor to the flame, $c.$b$bHere among the Earthen Ring, we simply honor the flame, rather than engage in other frivolities.$b$bHere, we will honor the flame as tradition dictates.  Will you join with us in honoring the flame, $n?' AS `src`, '尽管有许多火焰被争夺、被熄灭又被重新点燃，但所有人都欢迎来向火焰致敬，$c。$b$b在这里，在大地之环中间，我们只是单纯地敬奉火焰，而不去参与其他无谓的喧闹。$b$b在这里，我们将按传统敬奉火焰。你愿意和我们一起向火焰致敬吗，$n？' AS `dst`
    UNION ALL SELECT 'While I miss Gilneas greatly, there\'s ancient ruins to explore!' AS `src`, '我虽然非常想念吉尔尼斯，但这里有古代遗迹可以探索！' AS `dst`
    UNION ALL SELECT 'Our brothers at Baradin Hold on Tol Barad are very busy and not always available when you need them.  I have been stationed here around the clock to help you with tasks they might have given you.' AS `src`, '我们在托尔巴拉德巴拉丁要塞的兄弟们非常忙碌，你需要他们时未必能联系上。我被安排在这里全天候值守，协助处理他们可能交给你的任务。' AS `dst`
    UNION ALL SELECT 'You seek power, yes? But will you walk the cursed path I do for it?' AS `src`, '你追求力量，对吧？可你愿意为此走上我这条被诅咒的道路吗？' AS `dst`
    UNION ALL SELECT 'My path is a dark and cursed one, $c. You do not wish to walk with me.' AS `src`, '我这条路阴暗且受诅咒，$c。你不会想和我同行的。' AS `dst`
    UNION ALL SELECT 'Welcome, my $g brother : sister;.  If you are here to train, then I would be delighted to train you.' AS `src`, '欢迎，我的 $g兄弟：姐妹;。如果你是来接受训练的，我很乐意训练你。' AS `dst`
    UNION ALL SELECT 'If you seek training in the Old Ways, I cannot help you.' AS `src`, '如果你想学习古老之道，我帮不了你。' AS `dst`
    UNION ALL SELECT 'There\'s a worgen druid by the name of Dareth just outside the city gates; he might be able to help you.$B$BBig beast of a fellow, covered in white leather and furs. You can\'t miss him.' AS `src`, '城门外有一位名叫达雷斯的狼人德鲁伊，他也许能帮你。$B$B一个大家伙，身上裹着白色的皮革和毛皮。你不会错过的。' AS `dst`
    UNION ALL SELECT 'Ye want Deepmountain Mining and Jewelcrafting, over on the northern side of The Great Forge.' AS `src`, '你要找深山采矿与珠宝加工，就在大熔炉北侧。' AS `dst`
    UNION ALL SELECT 'A blacksmith and his assistant can be found working in the Warrior\'s Terrace, near the armor and weapon vendors there.' AS `src`, '你可以在战士平台上找到一位铁匠和他的助手，就在那儿的护甲和武器商附近。' AS `dst`
    UNION ALL SELECT 'I can teach the art of cooking.\r\n\r\nAre you looking to learn?' AS `src`, '我可以教授烹饪之道。\n\n你是来学的吗？' AS `dst`
    UNION ALL SELECT 'Speak to Paymaster Lendry on the second floor of the barracks.\r\n\r\n\r\n\r\nHe can arrange to store your goods with Theramore\'s treasury.' AS `src`, '去找营房二楼的军需官伦德里谈谈。\n\n\n\n他可以安排把你的货物存放在塞拉摩的金库。' AS `dst`
    UNION ALL SELECT 'Look for Jensen Farran near the archery range.' AS `src`, '在靶场附近找詹森·法兰。' AS `dst`
    UNION ALL SELECT 'You\'ll find Horace Alder pacing about above the ground level of Lady Proudmoore\'s tower.' AS `src`, '你会在普罗德摩尔女士塔楼的地面层上方找到霍勒斯·阿尔德，他正在那儿来回踱步。' AS `dst`
    UNION ALL SELECT 'Look for Brother Karman overseeing training at the combat dummies outside the barracks.' AS `src`, '去找卡曼修士，他在营房外的训练假人旁监督训练。' AS `dst`
    UNION ALL SELECT 'Look for Allen Bright at the sparring ring near the barracks.\r\n\r\n\r\n\r\nHe and Doctor Gustaf VanHowzen oversee the training of the isle\'s healers.' AS `src`, '在营房附近的比试圈找艾伦·布莱特。\n\n\n\n他和古斯塔夫·范豪森医生一起监督岛上治疗者的训练。' AS `dst`
    UNION ALL SELECT 'I\'m not certain. Try asking Calia Hastings, by the docks. I\'m told she has connections to SI:7.' AS `src`, '我不太确定。你去码头那边问问卡莉亚·哈斯廷斯。听说她和军情七处有联系。' AS `dst`
    UNION ALL SELECT 'A shaman...?\r\n\r\n\r\n\r\nThere\'s a rather rough-looking dwarven lass staying in Theramore\'s inn; I believe she came to visit an old friend of hers here.\r\n\r\n\r\n\r\nShe might be able to help you.' AS `src`, '萨满……？\n\n\n\n塞拉摩的旅店里住着一位看起来很粗犷的矮人姑娘；我想她是来探望这儿的一位老朋友的。\n\n\n\n她也许能帮你。' AS `dst`
    UNION ALL SELECT 'Well... ah... don\'t tell her I sent you, but look for a red-robed woman above the ground level of the central tower.\r\n\r\n\r\n\r\nRedia Vaunt is her name. But do not mention me!' AS `src`, '嗯……啊……别说是我让你去的，去找中央塔楼地面层上方那位穿红袍的女子。\n\n\n\n她叫蕾迪娅·沃恩特。但千万别提到我！' AS `dst`
    UNION ALL SELECT 'Report to Captain Evencane on the second level of the barracks. He can see to your training.' AS `src`, '向营房二层的伊文凯恩队长报到。他可以负责你的训练。' AS `dst`
    UNION ALL SELECT 'Alchemist Narett and Brant Jasperbloom teach Alchemy and Herbalism out of a small shop here; they\'ll be able to help you.' AS `src`, '炼金师纳雷特和布兰特·贾斯珀布鲁姆在这儿的一间小店里教授炼金术和草药学；他们能帮你。' AS `dst`
    UNION ALL SELECT 'I know that one of those visiting Woolybush dwarves is an archaeologist.\r\n\r\n\r\n\r\nI think it\'s the wife, Faena. They\'re both explorers of some sort. Look for them in the inn.' AS `src`, '我知道来访问的伍利布什矮人里有一位是考古学家。\n\n\n\n我想是那位妻子，法埃娜。他们俩都算是探险家。去旅店里找他们。' AS `dst`
    UNION ALL SELECT 'Ask for Marie Holdston at the smithy.' AS `src`, '到铁匠铺找玛丽·霍尔斯顿。' AS `dst`
    UNION ALL SELECT 'Craig Nollward works the inn\'s kitchen. He\'ll be able to help you.' AS `src`, '克雷格·诺尔沃德在旅店厨房干活。他能帮你。' AS `dst`
    UNION ALL SELECT 'Lissah Spellwick, at the top of mage tower, is the mistress of Lady Jaina\'s enchanters.' AS `src`, '法师塔顶的莉莎·斯佩尔维克是吉安娜女士的附魔师首领。' AS `dst`
    UNION ALL SELECT 'Look for Caz Twosprocket at the smithy.' AS `src`, '到铁匠铺找卡兹·双链轮。' AS `dst`
    UNION ALL SELECT 'Doctor Gustaf VanHowzen works on the ground level of the barracks.' AS `src`, '古斯塔夫·范豪森医生在营房的地面层工作。' AS `dst`
    UNION ALL SELECT 'Michael Crowe, down by the docks, can teach you anything you need to know about catching and gutting fish.' AS `src`, '码头的迈克尔·克罗能教你一切关于捕鱼和剖鱼的知识。' AS `dst`
    UNION ALL SELECT 'Look for Theoden Manners at the top of Lady Proudmoore\'s tower.' AS `src`, '在普罗德摩尔女士塔楼顶层找西奥登·曼纳斯。' AS `dst`
    UNION ALL SELECT 'I\'m certain that one of the visiting Woolybush dwarves is a jewelcrafter.\r\n\r\n\r\n\r\nI believe it\'s the husband, Ingo. They\'re both explorers of some sort. Look for them in the inn.' AS `src`, '我确定来访问的伍利布什矮人里有一位是珠宝加工师。\n\n\n\n我想是那位丈夫，因戈。他们俩都算是探险家。去旅店里找他们。' AS `dst`
    UNION ALL SELECT 'Seek out the Tanwell brothers in Theramore\'s inn. One of them will be able to help you.' AS `src`, '去塞拉摩的旅店找坦威尔兄弟。他们中的一个能帮你。' AS `dst`
    UNION ALL SELECT 'Look out for the dwarf, Kerik, outside Theramore\'s smithy.\r\n\r\n\r\n\r\nHe\'s a drunkard and a bit free with the explosives, but he\'s friendly enough and knows his way around a mine.' AS `src`, '去塞拉摩铁匠铺外找那个矮人凯里克。\n\n\n\n他是个酒鬼，用起炸药来也大大咧咧，不过人挺友善，而且对矿井很在行。' AS `dst`
    UNION ALL SELECT 'You\'ll want to find Sansha MacVince, just outside Theramore\'s stables.' AS `src`, '你要找珊莎·麦克文斯，就在塞拉摩马厩外面。' AS `dst`
    UNION ALL SELECT 'Timothy Worthington works out of the second floor of one of Theramore\'s larger buildings. He\'ll do you right.' AS `src`, '蒂莫西·沃辛顿在塞拉摩一栋较大的建筑二层工作。他办事靠得住。' AS `dst`
    UNION ALL SELECT 'I have no time for a sermon now, $c. Seek your knowledge elsewhere.' AS `src`, '我现在没工夫说教，$c。去别处求知吧。' AS `dst`
    UNION ALL SELECT 'The Light gives us the strength and magic to triumph.' AS `src`, '圣光赐予我们胜利所需的力量与魔法。' AS `dst`
    UNION ALL SELECT 'I apologize, $c. I mistook you for someone with a spine. Begone; our secrets are not for untrained ears.' AS `src`, '抱歉，$c。我看错你了，还以为你有点骨气。走吧；我们的秘密不是给未经训练的耳朵听的。' AS `dst`
    UNION ALL SELECT 'We have little to discuss, $c. Perhaps you should seek other, more like-minded individuals.' AS `src`, '我们没什么可谈的，$c。也许你该去找些更志同道合的人。' AS `dst`
    UNION ALL SELECT 'Do you prefer guns or bows?' AS `src`, '你更喜欢枪还是弓？' AS `dst`
    UNION ALL SELECT 'I train only warriors, $c. You\'ll have to look elsewhere.' AS `src`, '我只训练战士，$c。你得另找别人。' AS `dst`
    UNION ALL SELECT 'Ours is a path for those with an iron will and unfaltering resolve. You seem to possess none of these traits, $c.' AS `src`, '我们这条路是给意志如铁、决心不移的人走的。你似乎一样都不具备，$c。' AS `dst`
    UNION ALL SELECT '$N, how may I further your training?' AS `src`, '$N，我该如何进一步指导你的训练？' AS `dst`
    UNION ALL SELECT 'If you seek training, I cannot help you.' AS `src`, '如果你想接受训练，我帮不了你。' AS `dst`
    UNION ALL SELECT 'It appears you took a wrong turn, $c.' AS `src`, '看来你走错路了，$c。' AS `dst`
    UNION ALL SELECT 'You come to join the fight, $c?' AS `src`, '你是来加入战斗的吗，$c？' AS `dst`
    UNION ALL SELECT 'Our ethereal technomancy has the ability to modify an item\'s arcane essence in ways previously unimaginable. We can also house items in a pocket dimension... for a small fee. See my associates for details.$B$BUnless you have something for me to examine?' AS `src`, '我们的虚灵科技能以过去难以想象的方式改造物品的奥术精华。我们还能把物品存放在口袋空间里……只需一点费用。详情请问我的同伴。$B$B除非你有东西要我看看？' AS `dst`
    UNION ALL SELECT 'Hey, hey!$B$BI\'m sure you can land a ring on a slow-moving turtle.$b$bWhat do you say?' AS `src`, '嘿，嘿！$B$B我肯定你能把环套到一只慢吞吞的乌龟身上。$b$b你说呢？' AS `dst`
    UNION ALL SELECT 'You give me a game token, and I\'ll give you ten rings. $B$BThrow the rings onto the Dubenko the Darkmoon Turtle over there... see the pole he\'s carrying on his shell?$b$bIf you don\'t land enough rings to win in one go, try again! Your points carry over into your next game.' AS `src`, '你给我一枚游戏币，我就给你十个环。$B$B把环套到那边那只暗月乌龟杜本科身上……看见他壳上扛着的那根竿子了吗？$b$b要是一轮还套不够赢的分数，就再来一次！你的分数会累计到下一局。' AS `dst`
    UNION ALL SELECT 'Setting up and maintaining the grounds is tough work...' AS `src`, '搭建和维护场地是件苦差事……' AS `dst`
    UNION ALL SELECT 'We\'ve got hammers, we\'ve got gnolls.$b$bIf you\'ve got a token, you can use the hammer to whack some gnolls.' AS `src`, '我们有锤子，我们有豺狼人。$b$b你要是有游戏币，就能用锤子敲那些豺狼人。' AS `dst`
    UNION ALL SELECT 'Looking for the old steam tonks?$b$bWell, we\'ve got some new ones for you to enjoy.$b$bNormally, it would cost two tokens to use a tonk remote.  But because of your military service, you get a discounted rate of one token.$b$bWe at the Darkmoon Faire thank you for your service.' AS `src`, '想找老式蒸汽坦克？$b$b嗯，我们给你准备了新的来玩。$b$b通常使用坦克遥控器要两枚游戏币。不过鉴于你的军旅贡献，给你一枚的优惠价。$b$b暗月马戏团感谢你的服役。' AS `dst`
    UNION ALL SELECT 'A trio of ethereal technomancers has set up shop in Stormwind, along the canal south of Cathedral Square.\r\n\r\n\r\n\r\n"The Three Winds," it\'s called. Look for the weird machinery and purple lights... you can\'t miss it.\r\n\r\n\r\n\r\nThey offer just the sort of services you\'re looking for.' AS `src`, '三个虚灵科技师在暴风城大教堂广场南边的运河旁开了家店。\n\n\n\n店名叫“三风”。找那些奇怪的机械和紫色的光……你不会错过。\n\n\n\n他们提供的正是你想要的服务。' AS `dst`
    UNION ALL SELECT 'No more games for you.' AS `src`, '别再玩游戏了。' AS `dst`
    UNION ALL SELECT 'You need Darkmoon Game Tokens to play.$b$bBuy them from any of the faire\'s Game Token vendors.$b$bI\'ll mark one on your map for you.' AS `src`, '你需要暗月游戏币才能玩。$b$b向马戏团任意游戏币商人购买。$b$b我会在地图上给你标出一位。' AS `dst`
    UNION ALL SELECT 'First, you give me a game token.  Next, I give you a mallet.  Then you\'ll see gnolls pop from the barrels in the play area.$B$BHit the gnolls with your mallet to score points.$b$BHere\'s where it gets tricky.  There are three different targets: regular gnolls, Hogger gnolls, and BABIES.$b$bRegular gnolls grant one point, while Hoggers count for three.  But babies?  Hitting a baby will knock you down and stun you... SO DON\'T HIT THE BABIES!$b$bIf you don\'t whack enough gnolls in one go, just spend another token!  The points you\'ve earned will carry over into your next game.' AS `src`, '首先，你给我一枚游戏币。然后，我给你一把木槌。接着你会看到豺狼人从场地的木桶里冒出来。$B$B用木槌敲豺狼人来得分。$b$b这里就有点讲究了。有三种目标：普通豺狼人、霍格豺狼人，还有“小宝宝”。$b$b普通豺狼人得一分，霍格得三分。可小宝宝呢？敲中小宝宝会把你击倒并昏迷……所以别敲小宝宝！$b$b要是一轮敲不够，就再花一枚游戏币！你已获得的分数会累计到下一局。' AS `dst`
    UNION ALL SELECT 'First, you give me one game token.  Then you find yourself in control of a steam tonk!$b$bYou have a limited amount of time to blast targets in the battlefield.  Each target you destroy earns you one point.$b$bBut watch out: The battlefield is also home to enemy tonks and zeppelins.  Getting hit by one of their shots damages your tonk.$b$bYour score will carry over from one tonk to the next, so don\'t worry if you explode.' AS `src`, '首先，你给我一枚游戏币。然后你就控制了一辆蒸汽坦克！$b$b你有有限的时间在战场上轰击目标。每摧毁一个目标得一分。$b$b但要小心：战场上还有敌方坦克和飞艇。被他们的炮火击中会损伤你的坦克。$b$b你的分数会从一辆坦克累计到下一辆，所以炸了也别担心。' AS `dst`
    UNION ALL SELECT 'First, I give you a pellet rifle in exchange for one Darkmoon Game Token.$B$BThen you shoot the targets that light up.$b$bIf you\'re fast enough to hit a target just after it\'s lit up, you get an extra point.$b$bIf you don\'t reach the score limit before your time\'s up, or you move away from the booth, don\'t worry: Your score carries over to the next game.' AS `src`, '首先，我用一枚暗月游戏币换给你一支弹丸步枪。$B$B然后你去射击亮起来的目标。$b$b如果你够快，在目标刚亮起时就打中，还能多得分。$b$b要是在时间到之前没达到分数上限，或者你离开了摊位，别担心：分数会累计到下一局。' AS `dst`
    UNION ALL SELECT 'Hello and welcome to the Darkmoon Faire Staging Area.$b$bThe portal here will take you to the Darkmoon Faire.$b$bBut if you have any questions before you go, I can answer them.' AS `src`, '你好，欢迎来到暗月马戏团集结区。$b$b这里的传送门会把你送到暗月马戏团。$b$b不过在出发之前，如果你有什么问题，我可以解答。' AS `dst`
    UNION ALL SELECT 'The Darkmoon Faire is filled with all sorts of amazing attractions.  We have a fortune teller, a concert, a fishing contest and a lot of games.$b$bWe are constantly expanding the faire with all manner of new attractions!$b$bAre there any attractions you\'d like more information on?' AS `src`, '暗月马戏团里有各种奇妙的游乐项目。我们有占卜师、音乐会、钓鱼比赛，还有很多游戏。$b$b我们一直在增添各种新的游乐项目！$b$b有哪项想了解更多吗？' AS `dst`
    UNION ALL SELECT 'Miniature tanks, or Tonks as we\'ve cleverly named them, have been a faire favorite for as long as I can remember.$b$bWe have two arenas dedicated for tonk battles.$b$bOne arena pits you against the clock as you race to destroy targets, and avoid the enemy tonks.  You just need a game token to play!$b$bThe other arena is a place where you can use your own tonks or MiniZeps to battle your friends.' AS `src`, '微型坦克——我们很巧妙地称之为“坦克”——从我有记忆起就是马戏团的最爱。$b$b我们有两个专门用于坦克对战的竞技场。$b$b其中一个竞技场让你与时间赛跑，冲去摧毁目标，同时躲避敌方坦克。玩一局只需一枚游戏币！$b$b另一个竞技场则是让你用自己的坦克或迷你飞艇和朋友对战的地方。' AS `dst`
    UNION ALL SELECT 'The Blastenheimer 5000 Ultra Cannon is a state-of-the-art single person projectile device.$b$bDelivering its payload at near the speed of a dragon, the cannon is the pride and joy of the Blastenheimer family, world renowned for their aeronautical and combustible feats!$B$BIf you\'d like to be launched through the skies to fly free as a bird, seek out Maxima Blastenheimer.' AS `src`, '布拉斯滕海默 5000 型超级大炮是最先进的单人投射装置。$b$b它以接近巨龙的速度投送载荷，是布拉斯滕海默家族的骄傲与欢乐——这个家族以航空与爆破壮举闻名于世！$B$B如果你想被射上天空、像鸟儿一样自由飞翔，就去找玛克西玛·布拉斯滕海默。' AS `dst`
    UNION ALL SELECT 'Whack-a-Gnoll is a fun-filled game of whacking... gnolls.$b$bIt\'s a new attraction, and quite popular among us... Well, Sayge isn\'t too fond of it.' AS `src`, '敲豺狼人是一种充满乐趣的敲……豺狼人游戏。$b$b这是新项目，我们这里还挺受欢迎的……嗯，赛格就不太喜欢它。' AS `dst`
    UNION ALL SELECT 'We like to make sure that faire goers of all ages can enjoy the games.$b$bRing Toss is a simple game where you try to land a ring on the back of a moving turtle.$b$bIt\'s one of my favorite games to play.' AS `src`, '我们希望各年龄段的马戏团游客都能享受游戏。$b$b套环是个简单的游戏，你要把环套到一只移动的乌龟背上。$b$b这是我最喜欢的游戏之一。' AS `dst`
    UNION ALL SELECT 'Rinling runs the shooting gallery.$b$bThere are only three targets to hit, and the faster you are, the better you do.$b$bPersonally, it\'s one of my favorite games.' AS `src`, '林灵经营射击场。$b$b只有三个目标要打，你越快，得分越高。$b$b就我个人而言，这是我最喜欢的游戏之一。' AS `dst`
    UNION ALL SELECT 'I highly recommend that you visit Sayge to get your fortune told.$b$bI know, I know... he\'s a gnoll.  But he\'s a very special gnoll with the power to divine your future!' AS `src`, '我强烈建议你去找赛格算个命。$b$b我知道，我知道……他是豺狼人。但他是个非常特别的豺狼人，有占卜你未来的能力！' AS `dst`
    UNION ALL SELECT 'Hello $c, and welcome to the Darkmoon Faire.$b$bThere is so much to do here at the faire that it can be a little overwhelming for our first time visitors. That\'s why I\'m here to help.$b$bDo you have any questions?' AS `src`, '你好 $c，欢迎来到暗月马戏团。$b$b这儿可玩的东西太多了，对第一次来的游客来说可能有点应接不暇。所以我在这儿帮忙。$b$b你有什么问题吗？' AS `dst`
    UNION ALL SELECT 'This set up sure is hard work.' AS `src`, '这套东西搭起来可真费劲。' AS `dst`
    UNION ALL SELECT 'I\'m sorry, but Lorna\'d be real mad if I let you take a horse.\r\n\r\nThey\'re only for those who are exalted with Gilneas!' AS `src`, '抱歉，可要是我让你牵走一匹马，洛娜会气疯的。\n\n这些马只给在吉尔尼斯达到崇拜的人！' AS `dst`
    UNION ALL SELECT 'Lorna said a truly brave adventurer helped rescue many of the horses near her family\'s orchard.\r\n\r\nI offered to take care of those that made it across the sea with us. I learned how from my mother and father, Light bless them!\r\n\r\nWere you interested in a fine Gilnean steed...?' AS `src`, '洛娜说有位真正勇敢的冒险者帮忙救下了她家果园附近的许多马。\n\n我主动提出照料那些随我们渡海过来的马。我是跟父亲母亲学的，愿圣光保佑他们！\n\n你对一匹上好的吉尔尼斯战马感兴趣吗……？' AS `dst`
    UNION ALL SELECT 'Mysteries and wonders surround us every day, not just at the faire.  We\'ve compiled a list of some of the wonders you may encounter in your every day business.  The Darkmoon Adventurer\'s Guide will help you navigate the wonders of the world.$b$bWith the guide in your possession, you may come across items you never knew existed.  Items you may have taken for granted in the past are now treasures that others long for.$b$bKeep the guide with you, and keep your eyes open for mystery.$b$bIf you happen to lose your guide, seek us out and we will replace it for free.' AS `src`, '神秘与奇观每天都围绕着我们，不只是马戏团里。我们整理了一份清单，列出你日常事务中可能遇到的种种奇观。《暗月冒险者指南》能帮你探索世界上的奇观。$b$b带着这本指南，你可能会遇到从未想过存在的物品。过去你习以为常的东西，如今成了别人渴望的珍宝。$b$b把指南带在身上，睁大眼睛寻找神秘吧。$b$b万一丢了指南，来找我们，我们会免费补发。' AS `dst`
    UNION ALL SELECT 'We waiting for tour guide.' AS `src`, '我们在等导游。' AS `dst`
    UNION ALL SELECT 'We just wait for guide.' AS `src`, '我们只是等导游。' AS `dst`
    UNION ALL SELECT 'Are you here to lead the tour?' AS `src`, '你是来带团的吗？' AS `dst`
    UNION ALL SELECT 'If you are not here to lead a tour, leave us.' AS `src`, '如果你不是来带团的，就离开我们。' AS `dst`
    UNION ALL SELECT 'Are you ready?' AS `src`, '你准备好了吗？' AS `dst`
    UNION ALL SELECT 'Were you looking to Reforge an item? I no longer provide such services.\r\n\r\n\r\n\r\nThe ethereals of "Three Winds" in Stormwind\'s Cathedral District will help you, though.\r\n\r\n\r\n\r\nAny of the city\'s guards can provide directions.' AS `src`, '你是来重铸物品的？我不再提供这类服务了。\n\n\n\n不过暴风城大教堂区的“三风”虚灵会帮你。\n\n\n\n城里任何卫兵都能给你指路。' AS `dst`
    UNION ALL SELECT 'Were you looking to Reforge an item? I no longer provide such services.\r\n\r\n\r\n\r\nThe ethereals of Orgrimmar\'s Drag will help you, though.\r\n\r\n\r\n\r\nAny of the city\'s guards can provide directions.' AS `src`, '你是来重铸物品的？我不再提供这类服务了。\n\n\n\n不过奥格瑞玛暗影裂口的虚灵会帮你。\n\n\n\n城里任何卫兵都能给你指路。' AS `dst`
    UNION ALL SELECT 'Don\'t stop now.$B$BYou still have time left to play!' AS `src`, '别停下。$B$B你还有时间继续玩！' AS `dst`
    UNION ALL SELECT 'This cannot be, is it finally over?  I must be dreaming again.' AS `src`, '这不可能，终于结束了吗？我一定又是在做梦。' AS `dst`
    UNION ALL SELECT 'Now you must usher in a new age... The age of mortals.' AS `src`, '现在你必须引领一个新时代……凡人的时代。' AS `dst`
    UNION ALL SELECT 'Praise the Light, one has finally answered the calling.' AS `src`, '赞美圣光，终于有人回应了召唤。' AS `dst`
    UNION ALL SELECT '<Eris nods>$B$BThe Eye has seen so many horrors and wonders.$B$BIt displays what it feels the one looking into it is most suited to see.' AS `src`, '<埃里斯点头>$B$B这只眼睛见过太多恐怖与奇观。$B$B它会显示它认为凝望者最该看到的东西。' AS `dst`
    UNION ALL SELECT 'You were. The Eye is never wrong.$B$BYou are a $c after all. A powerful $c, if the Eye showed you this horrible memory.$B$BYou have come for redemption, yet you yourself do not realize this... Do you?' AS `src`, '你就是。这只眼睛从不出错。$B$B你毕竟是个 $c。如果这只眼睛让你看到这段可怕的记忆，那你就是个强大的 $c。$B$B你是来寻求救赎的，可你自己还没意识到……不是吗？' AS `dst`
    UNION ALL SELECT 'I know you will, $N.$B$BI myself am a priestess, though, unlike you I am long since gone from this world. My spirit, however, remains here, as do the spirits of the thousands who were brutally slain by the mad Prince, Arthas Menethil and his legion of undeath.' AS `src`, '我知道你会的，$N。$B$B我自己也是一位女祭司，只是不像你，我早已离开这个世界。不过我的灵魂仍留在这里，还有数千名被疯狂的阿尔萨斯·米奈希尔王子及其亡灵军团残杀者的灵魂也一样。' AS `dst`
    UNION ALL SELECT 'I never stated that you were here to redeem yourself, $c. You are here to redeem me and the innocents murdered while trying to escape Stratholme.$B$BMy spirit and the spirit of those lost are bound here, cursed to endlessly relive our own tragic deaths.' AS `src`, '我从没说过你是来为自己赎罪的，$c。你是来为我、为那些在逃离斯坦索姆时被杀害的无辜者赎罪的。$B$B我和那些亡者的灵魂被束缚在此，被诅咒着无休止地重演我们自己的惨死。' AS `dst`
    UNION ALL SELECT 'You must do what I could not: Save the peasants that were cut down while fleeing from Stratholme.$B$BThey will walk towards the light, you must ensure their survival. Should too many fall, our cursed existence shall continue - you will have failed.$B$BEvery ability, prayer and spell that you have learned will be tested. May the Light protect you, $N.' AS `src`, '你必须做我做不到的事：救下那些在逃离斯坦索姆时被砍倒的农民。$B$B他们会走向光明，你必须确保他们活下来。如果倒下的人太多，我们这被诅咒的存在就将延续下去——你就失败了。$B$B你学到的每一样能力、每一句祈祷、每一个法术都将受到考验。愿圣光护佑你，$N。' AS `dst`
) AS `m` ON `m`.`src` = `a`.`text0_0`
SET `a`.`text0_0` = `m`.`dst`;
-- One indexed pass replaces 19 single-row UPDATEs on `npc_text`.`text0_1`.
UPDATE `npc_text` AS `a`
JOIN (
    SELECT 'Well, if it isn\'t a young, bristling $c, no doubt drawn here by talk of my exploits in fields of battle!$B$BNo time for stories now, for there are great, important deeds that need doing!  So if you\'re looking for glory, then luck shines on you today...' AS `src`, '哦，可不是个年轻气盛的 $c 嘛，多半是听说了我在战场上那些事迹才来到这儿的！$B$B不过现在没工夫讲故事，还有了不起的大事等着办呢！所以你要是来找荣耀的，今天可算走运了……' AS `dst`
    UNION ALL SELECT 'What?' AS `src`, '什么？' AS `dst`
    UNION ALL SELECT 'Welcome, champions! All of our attempts at grounding her have failed. We could use a hand in bringing her down with these harpoon guns.' AS `src`, '欢迎，勇士们！我们所有想把她拽下来的尝试都失败了。要是你们能用这些鱼叉炮帮忙把她打下来，那可就帮大忙了。' AS `dst`
    UNION ALL SELECT 'Ahh... so it is, so it is. Carry on then. Carry on t\'yer death.' AS `src`, '啊……是这样，是这样。那就继续吧。继续走向你的死亡吧。' AS `dst`
    UNION ALL SELECT 'Hey there, friend. My name\'s Remy. I\'m from Redridge to the east, and came here looking for business, looking for business. You got any...got any??' AS `src`, '嘿，朋友。我叫雷米。我从东边的赤脊山来，到这儿想找点生意，找点生意。你有没有……有没有？？' AS `dst`
    UNION ALL SELECT 'Hello friend.' AS `src`, '你好，朋友。' AS `dst`
    UNION ALL SELECT 'A thunderous voice bellows from the stone...$B$BI sense your Medallion of Station, cultist, but you have no ring of lordship?  Are you truly a commander of the Twilight\'s Hammer, or do you merely run errands for your betters?' AS `src`, '一个雷鸣般的声音从石头中传来……$B$B我感应到了你的统御徽记，教徒，可你却没有领主之戒？你真是暮光之锤的指挥官，还是只在替你的上级跑腿？' AS `dst`
    UNION ALL SELECT 'The journal of Jandice Barov is filled with rantings and ravings about the undead. Towards the end of the book is what appears to be a tailoring pattern for the creation of a felcloth bag. This bag is used by warlocks to store soul shards. Do you wish to copy the pattern into your own journal?' AS `src`, '詹迪斯·巴罗夫的日记里满是对亡者的胡言乱语。书的末尾似乎是一份制作魔布包的裁缝图样。这种包被术士用来存放灵魂碎片。你想把图样抄进自己的日记吗？' AS `dst`
    UNION ALL SELECT 'The journal of Jandice Barov is filled with rantings and ravings about the undead. Towards the end of the book is what appears to be a tailoring pattern for the creation of a felcloth bag. This bag is used by warlocks to store soul shards. You already know how to create this bag.' AS `src`, '詹迪斯·巴罗夫的日记里满是对亡者的胡言乱语。书的末尾似乎是一份制作魔布包的裁缝图样。这种包被术士用来存放灵魂碎片。你已经会制作这种包了。' AS `dst`
    UNION ALL SELECT 'The Blastenheimer 5000 Ultra Cannon is a state-of-the-art single person projectile device. Delivering its payload at near the speed of a dragon, the cannon is the pride and joy of the Blastenheimer family, world renown for their aeronautical and combustible feats!$B$BIf you\'d like to be launched through the skies to fly free as a bird, seek out Maxima Blastenheimer on the east end of the faire. I hear that she\'s placed a target ring way over on Crystal Lake for you to aim for as you sail through the air!' AS `src`, '布拉斯滕海默 5000 型超级大炮是最先进的单人投射装置。它以接近巨龙的速度投送载荷，是布拉斯滕海默家族的骄傲与欢乐——这个家族以航空与爆破壮举闻名于世！$B$B如果你想被射上天空，像鸟儿一样自由飞翔，就去集市东头找玛克西玛·布拉斯滕海默吧。我听说她在水晶湖那边设了一个目标环，让你在空中飞过时可以瞄准！' AS `dst`
    UNION ALL SELECT 'Thanks for getting that ore and taking it to Magister Quallestis, $c. I suppose that I should head back, but I\'m afraid of the punishment I\'m going to receive because I couldn\'t get the ore myself.$B$BDon\'t tell the magister, ok?' AS `src`, '多谢你把那些矿石取来并交给了奎利斯提斯法师，$c。我想我该回去了，可我又怕因为没能亲自拿到矿石而受罚。$B$B别告诉法师，好吗？' AS `dst`
    UNION ALL SELECT 'Your continued help against the Burning Legion would still be appreciated. Thrall could use your assistance in his encampment to the west of here.' AS `src`, '你继续对抗燃烧军团的帮助依然会受欢迎。萨尔在西边的营地里需要你的协助。' AS `dst`
    UNION ALL SELECT 'Congratulations! A great victory has been won today.' AS `src`, '恭喜！今天赢得了伟大的胜利。' AS `dst`
    UNION ALL SELECT 'Forgetting your skill in Spellfire Tailoring is not something to do lightly.  If you choose to abandon it you will forget all recipes that require Spellfire Tailoring to create!$b$bAre you absolutely sure?$B' AS `src`, '忘记你在魔火裁缝上的技能可不是件小事。如果你选择放弃，你将忘记所有需要魔火裁缝才能制作的配方！$b$b你绝对确定吗？$B' AS `dst`
    UNION ALL SELECT 'Forgetting your skill in Potion Mastery is not something to do lightly.$B$BAre you absolutely sure?' AS `src`, '忘记你在药剂专精上的技能可不是件小事。$B$B你绝对确定吗？' AS `dst`
    UNION ALL SELECT 'The celebration of the natural processes of the world is silly; it\'s going to happen whether we celebrate or not! But it\'s a great excuse for sugar!' AS `src`, '庆祝世界自然的进程这种事很傻；不管我们庆不庆祝，它都会发生！不过这是个吃糖的好借口！' AS `dst`
    UNION ALL SELECT 'Why do we celebrate Pilgrim\'s Bounty...? Who can say. Habit, I suppose. I certainly can\'t taste any of it.$B$BPumpkin pie, virulent plagues... Does it really matter WHAT we\'re cooking up?' AS `src`, '我们为什么要庆祝朝圣者的恩典……？谁知道呢。大概是习惯吧。反正我什么都尝不出来。$B$B南瓜派、致命的瘟疫……我们在做什么真的重要吗？' AS `dst`
    UNION ALL SELECT 'You lookin\' for trainin\'? No can do. I ain\'t your gal.' AS `src`, '你想学点什么？不行。我不是你要找的人。' AS `dst`
    UNION ALL SELECT 'The horde have been relentless out here.  Feels like we are fighting two battles at one time.\r\n\r\n' AS `src`, '部落在这边毫不留情。感觉我们同时在打两场仗。\n\n' AS `dst`
) AS `m` ON `m`.`src` = `a`.`text0_1`
SET `a`.`text0_1` = `m`.`dst`;
